window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"vid-judge300-001","module":"panduan","prompt":"行政确认是指行政机关依法对相对方的法律地位、法律关系和法律事实进行甄别，给予确定、认可、证明并予以宣告的具体行政行为。根据上述定义，下列属于行政确认的是","options":["交管部门为李某的新车核发行驶证","市场监管局对违规商家作出罚款决定","民政局依法颁发结婚证书","公安部门对打架斗殴者处以行政拘留"],"answer":2,"explanation":"结婚证书是对婚姻法律关系的确定、认可和证明，属于行政确认。A项核发行驶证属于行政许可，是赋予相对方从事特定活动的资格，不是对既有法律事实的甄别宣告；B项罚款和D项行政拘留均属于行政处罚，是对违法行为的制裁。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-002","module":"panduan","prompt":"机会成本是指为了得到某种东西而所要放弃另一些东西的最大价值。根据上述定义，下列体现了机会成本的是","options":["小张花5万元买了一台设备，五年后以3万元卖出","小王把准备买房的100万元用于开店，放弃了房产增值的50万元","小李的店铺本月收入比上月减少2万元","小赵买股票亏损1万元，卖掉后转买基金"],"answer":1,"explanation":"放弃房产增值的50万元正是为了开店而放弃的其他选择中的最大价值，属于机会成本。A项是资产的折价处置，属于实际损失；C项是经营收入的环比下降，没有体现放弃备选方案；D项是投资亏损后的转换行为，放弃的是已经亏损的股票而非最大价值。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-003","module":"panduan","prompt":"投资中的“理性人假设”认为决策者会以自身利益最大化为目标，在约束条件下做出最优选择。根据上述定义，下列最不符合理性人假设的是","options":["李某比较三款基金的历年收益后买入其中一款","王某在股市大跌时恐慌性抛售全部持仓，事后追悔莫及","周某为省运费选择在促销期间集中采购原材料","吴某测算两种通勤方式的金钱与时间成本后选择骑行"],"answer":1,"explanation":"恐慌性抛售是情绪驱动的非最优决策，事后追悔说明并非利益最大化选择，最不符合理性人假设。A项比较收益、C项节省运费、D项测算成本均是在权衡后做出的最优选择，符合理性人假设。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-004","module":"panduan","prompt":"吸收犯是指一个犯罪行为因为是另一个犯罪行为的必经阶段、组成部分或当然结果，而被另一个犯罪行为吸收，仅按吸收之罪定罪处罚的犯罪形态。根据上述定义，下列构成吸收犯的是","options":["陈某伪造身份证后又用伪造的身份证实施诈骗","林某入户盗窃，非法进入住宅是盗窃行为的必经过程","赵某先后盗窃两次，两次均独立构成盗窃罪","孙某故意伤害他人后，又将被害人财物强行取走"],"answer":1,"explanation":"非法进入住宅是入户盗窃的必经阶段，被盗窃罪吸收，仅以盗窃罪论处，构成吸收犯。A项伪造身份证与诈骗是手段行为与目的行为，通常按牵连犯处断而非吸收犯；C项两次盗窃是连续犯；D项伤害后取财可能另构成抢劫或数罪并罚，不属于必经阶段的吸收。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-005","module":"panduan","prompt":"韦伯定律指出，感觉的差别阈限随原来刺激量的变化而变化，且表现为一定的规律性，即差别阈限与原刺激量的比值是一个常数。根据上述定义，下列能用韦伯定律解释的是","options":["在安静房间里，手表滴答声清晰可闻；在嘈杂车间里则完全听不见","买10元的商品便宜1元很敏感，买1000元的商品便宜1元几乎无感","长时间闻某种气味后，会逐渐感觉不到该气味","强光刺眼时人会闭上眼睛，稍后逐渐适应"],"answer":1,"explanation":"原刺激量越大（1000元），能察觉的差别越大（差别阈限越高），便宜1元便无感；10元时差别阈限小，1元即敏感，正是差别阈限与原刺激量成比例的体现。A项是绝对阈限受背景噪音影响；C项是感觉适应；D项是明适应过程。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-006","module":"panduan","prompt":"沉没成本是指已经发生且无法收回的支出。理性决策不应受沉没成本影响。根据上述定义，下列决策最不受沉没成本影响的是","options":["电影很难看，但小李觉得票钱不能白花，坚持看完","项目已投入500万且前景黯淡，董事会经评估后果断终止项目","王女士排队长达两小时，因舍不得放弃坚持等位","老周装修已花30万，发现材料有安全隐患仍继续使用原方案"],"answer":1,"explanation":"董事会根据前景评估决定终止，不受已投入的500万左右，是完全依据未来收益的理性决策。A、C、D三项均因已付出的票钱、时间、装修款而继续坚持错误选择，正是受沉没成本影响的典型表现。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-007","module":"panduan","prompt":"商品倾销是指一国厂商以低于正常价值的价格向另一国市场销售商品，以排挤竞争对手、占领市场的行为。根据上述定义，下列构成商品倾销的是","options":["某企业因换季对过季服装全场五折促销","某国粮商以每吨低于其国内市场价三成的价格向他国大量出售大豆","某国以补贴价向受灾国家无偿援助大量药品","某公司将产品以国内同价出口到他国并缴纳相应关税"],"answer":1,"explanation":"以低于正常价值（其国内市场价）的价格向他国销售，意在排挤对手，构成倾销。A项是国内换季促销，不是跨国低价销售；C项是无偿援助，不构成销售；D项以同价出口且正常缴税，不满足低于正常价值的条件。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-008","module":"panduan","prompt":"天花板效应是指在测评中，由于题目过于容易，导致大部分被试都取得接近满分的高分，从而无法有效区分被试实际水平差异的现象。根据上述定义，下列属于天花板效应的是","options":["某次高数考试题目极难，全班平均分仅28分","某岗位笔试题目过于基础，全体应聘者均在95分以上，排名难分高下","某体质测试中部分考生因故缺考，成绩未计入统计","某心理量表中部分题目表述模糊，被试普遍反映看不懂"],"answer":1,"explanation":"题目过于容易导致所有人接近满分、无法区分差异，是典型的天花板效应。A项是题目过难导致低分，属于地板效应；C项是缺考问题，与题目难度无关；D项是量表表述问题导致的测量误差。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-009","module":"panduan","prompt":"第三方支付是指具备一定实力和信誉保障的独立机构，通过与银行签约，提供与银行支付结算系统接口的网络支付模式。根据上述定义，下列属于第三方支付的是","options":["顾客用现金购买地铁票","顾客在商场购物时直接刷银行卡付款","企业之间通过银行对公账户转账支付货款","顾客在某购物平台下单后，货款先由平台托管，确认收货后再划转给商家"],"answer":3,"explanation":"独立机构（平台）与银行签约提供结算接口，货款经平台托管中转，属于第三方支付。B项刷卡是银行直接结算；C项对公转账是银行间直接支付；A项现金支付不涉及任何网络支付模式。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-010","module":"panduan","prompt":"晕轮效应又称光环效应，指人们在评价他人时，由于对方某一特征突出，从而推及其其他方面也具有相似特征的认知偏差。根据上述定义，下列属于晕轮效应的是","options":["考官根据评分标准逐项打分，各项得分互不影响","面试官因为应聘者谈吐出众，便认为其专业能力、团队意识同样出色","小李因为同事曾迟到一次，就认定其工作一定马虎","王老师认为成绩好的学生更可能遵守纪律，遂重点观察成绩差的学生"],"answer":1,"explanation":"由谈吐这一个突出特征推及专业能力、团队意识等其他方面，是以点概面的光环效应。A项逐项打分客观独立，无偏差；C项是由单一负面事件推及整体品质，虽也是偏差但属于以偏概全的刻板印象路径，且晕轮效应通常由突出特征泛化，C项更接近首因效应或成见；注意与A相比，A是典型的由一特征泛化到多特征。D项是基于统计推断的观察策略，不属于对个体的评价偏差。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-011","module":"panduan","prompt":"税收法定原则是指税收的征收和缴纳必须依照法律规定的标准和程序进行，征税机关不得擅自变更征税要素。根据上述定义，下列符合税收法定原则的是","options":["某市税务局严格依照法律规定的税率向企业征收企业所得税","某县税务部门为招商引资，自行决定对本地企业减半征收增值税","某税务人员口头承诺对个体户免税两年","某税务局根据人情关系调整个别企业的纳税申报额"],"answer":0,"explanation":"严格依照法律规定的税率征税，符合税收法定原则。B项自行决定减半征收，C项口头承诺免税，D项按人情调整税额，均属于擅自变更征税要素，违背税收法定原则。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-012","module":"panduan","prompt":"绿色贸易壁垒是指一国以保护环境、生态和人类健康为由，通过制定严格的环境技术标准，对外国商品进口采取的准入限制或禁止措施。根据上述定义，下列属于绿色贸易壁垒的是","options":["某国因外交争端宣布暂停从某国进口全部商品","某国对进口汽车和本国汽车征收相同税率的消费税","某国以进口水产品的抗生素残留超标为由，禁止相关产品入境","某国对进口奢侈品征收高额关税以增加财政收入"],"answer":2,"explanation":"以保护人类健康为由（抗生素残留危害健康），通过卫生技术标准限制进口，属于绿色贸易壁垒。B项内外同税，不构成歧视性限制；A项因外交争端的全面禁运属于政治性措施；D项以财政收入为目的的高关税属于普通关税壁垒。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-013","module":"panduan","prompt":"知觉的整体性是指人在知觉过程中，把由多种属性和部分组成的对象知觉为一个统一的整体的特性。根据上述定义，下列体现知觉整体性的是","options":["老王听到楼下喇叭声就知道是收废品的来了","小明能准确记住三个月前看过的一部电影的片名","一幅由许多碎片组成的拼贴画，观者依然把它看成一张人脸","小赵闭上眼睛能回忆起教室黑板上板书的内容"],"answer":2,"explanation":"由多个碎片组成的刺激被知觉为统一的人脸，是把部分整合为整体的体现。B项是记忆而非知觉；A项是借助经验作出的推理判断，属于知觉的理解性；D项是表象回忆而非对当前刺激的知觉。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-014","module":"panduan","prompt":"法定代理是指依照法律的规定，由一定身份的人直接代理无民事行为能力人或者限制民事行为能力人实施民事法律行为的代理。根据上述定义，下列属于法定代理的是","options":["公司法定代表人以公司名义签订采购协议","张某出具授权委托书，请朋友代签购房合同","村委会指定律师代理一起经济纠纷诉讼","母亲代八岁的儿子签署校外培训合同"],"answer":3,"explanation":"母亲基于法律规定的监护身份代理无民事行为能力人（八岁儿童为限制民事行为能力人，签署与其年龄不相符的合同须代理）实施民事法律行为，属于法定代理。B项是委托代理；C项是指定代理情形；A项法定代表人的行为是代表行为，不属于代理无行为能力人的法定代理。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-015","module":"panduan","prompt":"破窗理论认为，环境中的不良现象如果被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列做法直接体现了依据破窗理论的治理思路的是","options":["对见义勇为者给予表彰和物质奖励","对重特大安全事故责任人从严从重追究刑责","在社区加装高清监控摄像头震慑犯罪","对轻微违章即时纠正，防止他人效仿形成风气"],"answer":3,"explanation":"及时修复第一扇被打破的窗（轻微违章即时纠正），防止仿效扩散，正是破窗理论的治理思路。B项针对的是已经严重的犯罪，属于重典治乱；C项是技术预防震慑；A项是正向激励。均不是针对不良现象放任会诱发仿效这一机制的直接运用。故本题选D。判断推理300题·听课讲义·第64页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-016","module":"panduan","prompt":"边际效用递减规律是指在一定时间内，随着消费者对某种商品消费量的连续增加，其从每增加一单位商品中获得的效用增量是递减的。根据上述定义，下列最能体现边际效用递减的是","options":["收藏家买到第10件藏品时比买到第1件更兴奋","烈日下干渴的人喝第一杯水最解渴，第二杯、第三杯带来的满足感逐渐降低","学生每天练习钢琴，水平稳步提高","企业扩大生产规模后单位成本随之下降"],"answer":1,"explanation":"每多喝一杯水的效用增量递减，是边际效用递减的典型例子。A项效用递增，C项是技能积累，D项是规模经济（成本递减），均不符合。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-017","module":"panduan","prompt":"保险代位求偿权是指在财产保险中，保险人赔偿被保险人损失后，代位取得向对损失负有责任的第三者请求赔偿的权利。根据上述定义，下列情形中保险公司可依法行使代位求偿权的是","options":["保险公司赔付后向投保时未如实告知健康状况的人寿保险投保人追偿","被保险人自身操作不当导致车辆受损，保险公司理赔后向被保险人追偿","被保险人的家庭成员故意砸毁投保车辆，保险公司在赔付后向其追偿","车主投保车损险后，车辆被他人追尾，保险公司赔付后向肇事方追偿"],"answer":3,"explanation":"第三者（肇事方）对损失负有责任，保险人赔付后取得代位求偿权，D项正确。B项责任人是被保险人本人，保险人不得向被保险人及其家庭成员行使代位求偿权（家庭成员故意造成损失的情形依《保险法》规定，保险人不得对被保险人的家庭成员或其组成人员行使代位请求赔偿的权利，除非其故意——注：现行法下家庭成员故意造成保险事故的，保险人可以追偿，但本题按定义要件应由第三者责任构成，C项家庭成员属于被保险人一方，且人寿保险不适用代位求偿）。综合定义要件，D项最贴合第三者责任的代位求偿。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-018","module":"panduan","prompt":"自我效能感是指个体对自己能否成功完成某一成就行为的主观判断与信心程度。根据上述定义，下列属于自我效能感的是","options":["小周坚信安全驾驶非常重要，牢记交通法规","小刘对驾驶技术很感兴趣，经常观看赛车比赛","小陈认为自己能通过下个月的驾照科目二考试","小吴考试通过后获得了强烈的喜悦和成就感"],"answer":2,"explanation":"对自己能否完成某一行为的主观判断，即我能行吗的信心评估，C项正确。B项是兴趣，A项是价值观念，D项是成功后的情绪体验（自我效能感是事前的判断）。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-019","module":"panduan","prompt":"转继承是指继承人在被继承人死亡之后、遗产分割之前死亡，其应继承的遗产转由其合法继承人继承的制度。根据上述定义，下列情形适用转继承的是","options":["老张的儿子先于老张去世，老张去世后由其孙辈代位继承","老王立下遗嘱将房产赠给保姆，老王死后保姆随即放弃受遗赠","老李去世次日，其子突发车祸身亡，老李的遗产由其孙辈依法继承","老赵去世后遗产分割完毕，其子随后将分得的房产转卖他人"],"answer":2,"explanation":"继承人在被继承人死亡后、遗产分割前死亡，其应继承份额转由自己的继承人继承，C项完全符合。B项是放弃受遗赠；A项是被继承人的子女先于被继承人死亡，属于代位继承；D项遗产已分割完毕，属于正常的财产处分。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-020","module":"panduan","prompt":"群体极化是指在群体讨论中，成员的观点朝着更极端的方向转移，使得原先的保守观点更保守、冒险观点更冒险的现象。根据上述定义，下列属于群体极化的是","options":["某辩论队赛前抽到反方立场，队员为赢得比赛认真准备反驳材料","某评审组各成员独立打分，最终取平均分作为项目评分","某投资群里多数人本就看好某股票，讨论后看涨态度愈发激进，重仓加码","某班级原本人人观望是否参加志愿活动，老师动员后大家踊跃报名"],"answer":2,"explanation":"原有倾向（看涨）经群体讨论后朝更极端方向（激进重仓）转移，属于群体极化。B项独立打分取平均，无群体互动；A项是角色任务驱动的立场准备；D项是权威动员引发的从众行为，且是从无倾向到统一行动，不是极端化转移。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-021","module":"panduan","prompt":"不当得利是指没有法律依据取得利益，致使他人受到损失的事实。根据上述定义，下列构成不当得利的是","options":["赵某经合同约定出售货物并收取货款","李某捡到他人遗失的手机后妥善保管并寻找失主","银行系统故障，客户王某账户被多打入2万元，王某明知且拒不退还","孙某接受亲戚明示赠与的一辆自行车"],"answer":2,"explanation":"无法律依据取得利益（多打入的2万元）致他人受损且拒不返还，构成不当得利。B项拾得遗失物并积极寻找失主，无拒不返还的得利状态持续恶化情形，且保管行为构成无因管理倾向；A项基于合同取得利益，有法律依据；D项受赠与取得利益，有法律依据。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-022","module":"panduan","prompt":"逆火效应是指当人们接触到推翻自己既有信念的信息时，反而会更加坚定原有信念的现象。根据上述定义，下列属于逆火效应的是","options":["小赵查证后发现传言不实，随即在群里澄清并道歉","老张坚信某保健品有效，子女出示权威检测报告后，他反而更强调自己服用后确实有效","某公司在被曝光数据造假后，公开道歉并公布整改措施","王教授的论文被指出错误后，他重新实验修正了结论"],"answer":1,"explanation":"既有信念被相反证据冲击后更加坚定，是逆火效应。B、C、D三项均在事实面前修正了原有认识，属于理性更新的正常反应。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-023","module":"panduan","prompt":"消费者剩余是指消费者为购买某种商品愿意支付的最高价格与其实际支付价格之间的差额。根据上述定义，下列体现消费者剩余的是","options":["小李愿为演唱会门票出价1500元，实际花800元买到，省下700元","商家促销时降价300元，吸引大批顾客抢购","老王花2000元买的手机一年后跌价至1200元","小赵议价时把标价500元的椅子砍到450元，成交后商家仍盈利"],"answer":0,"explanation":"愿付最高价1500元与实际支付800元之差700元，正是消费者剩余。B项是商家降价促销；C项是资产贬值，与购买时的愿付价格无关；D项只体现议价成交和商家利润，未给出愿付最高价。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-024","module":"panduan","prompt":"首因效应指交往双方形成的第一次印象对今后交往关系的影响，即先入为主带来的效果。根据上述定义，下列属于首因效应的是","options":["共事三年后，同事间对彼此的评价日趋客观全面","新员工第一天着装得体、谈吐清晰，领导此后一直对其印象颇佳","评委在多轮面试中按统一量表逐项记录并汇总打分","某员工长期表现优异，偶有失误时领导也愿意体谅"],"answer":1,"explanation":"第一次见面形成的良好印象持续影响后续评价，是首因效应。A项是长期互动带来的全面认知，恰是首因效应消退；C项是标准化测评，无印象偏差；D项是近因效应或晕轮效应的例外宽容，由长期表现累积而成，不是第一印象的作用。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-025","module":"panduan","prompt":"留置权是指债权人按照合同约定占有债务人的动产，债务人不履行到期债务时，债权人有权依法留置该财产并优先受偿的担保物权。根据上述定义，下列成立留置权的是","options":["修车厂按合同占有客户送修的车辆，客户拒不支付修理费，修理厂留置车辆","银行依据贷款合同对借款人提供的房产享有优先受偿权","出租人在承租人欠租时，扣留承租人留在房屋内的行李","卖方在买方拒付货款时，宣布解除合同并要求返还货物"],"answer":0,"explanation":"修车厂合法占有债务人动产（送修车辆），债务人不履行到期债务时依法留置并优先受偿，完全符合定义。B项是不动产抵押权；C项扣留行李缺乏合同约定的占有依据，且行李非合同标的动产，不成立留置；D项是合同解除权而非担保物权。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-026","module":"panduan","prompt":"禀赋效应是指当个人一旦拥有某项物品，其对物品价值的评价会比未拥有时显著提高的现象。根据上述定义，下列属于禀赋效应的是","options":["老陈拿到公司发的纪念手表后，觉得它比商场同款更珍贵，不愿出售","小林在商场试戴项链前就觉得它物有所值，果断买下","周先生卖出持有多年的股票后，又以更高价买回同款股票","吴女士对比三家店铺后，选择价格最低的一家购买家电"],"answer":0,"explanation":"拥有之后价值评价显著提高（比同款更珍贵、不愿出售），是禀赋效应。B项是拥有前的判断，C项是交易行为本身，D项是理性比价。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-027","module":"panduan","prompt":"有限责任是指股东仅以其认缴的出资额为限对公司债务承担责任，公司以其全部财产对公司债务承担责任。根据上述定义，下列体现有限责任的是","options":["某公司破产清算，股东张某以其认缴的50万元出资为限承担责任，个人房产不受影响","个体工商户老赵经营失败后，以全部家庭财产清偿债务","合伙人刘某对合伙企业债务承担无限连带责任","某公司因侵权被判赔偿，法院执行公司全部资产"],"answer":0,"explanation":"股东以认缴出资额为限担责、个人财产与公司债务隔离，正是有限责任。B项个体户承担无限责任，C项是合伙的无限连带责任，D项是公司以其全部财产担责（这是公司责任，不是股东的有限责任，且定义的核心主体是股东）。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-028","module":"panduan","prompt":"工作丰富化是指通过赋予员工更多的自主权和责任感，使其工作内容更具挑战性和意义感，从而提高工作积极性的管理方式。根据上述定义，下列属于工作丰富化的是","options":["公司让资深客服自主处理客诉并参与服务流程改进，承担相应责任","公司在流水线上增加一道质检工序，员工工作时长随之增加","公司将两名员工的岗位进行轮换，各自学习新的操作","公司按季度对绩效优秀的员工发放奖金"],"answer":0,"explanation":"赋予自主权、增加责任感、提升挑战与意义，符合工作丰富化的核心（纵向扩展）。B项只是增加工作量，属于工作扩大化甚至负担加重；C项是岗位轮换，工作深度未变；D项是物质激励。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-029","module":"panduan","prompt":"刑法上的原因自由行为是指行为人故意或过失使自己陷入无责任能力状态，并在该状态下实施法益侵害行为的情形。根据上述定义，下列属于原因自由行为的是","options":["醉酒后误将他人财物当作自己的拿走","患精神分裂症期间在无辨认能力状态下突发伤人，此前无任何过错","明知自己饮酒后会失控伤人，仍大量饮酒并在酒后殴打他人","服用医生开具的助眠药物后正常入睡"],"answer":2,"explanation":"故意使自己陷入无/限制责任能力状态（明知酒后失控仍饮酒）并在该状态下实施侵害，属于原因自由行为，依法应负刑事责任。B项是真正的精神病人发病，无原因过错，不负刑事责任；A项若因醉酒致辨认能力减弱，同样落入原因自由行为范畴——但A项表述为误拿，无伤害故意且情节存疑，与C项相比，C项是定义最典型的故意型原因自由行为；D项是正常服药行为。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-030","module":"panduan","prompt":"目标管理是以目标为导向，以人为中心，以成果为标准，使组织和个人取得最佳业绩的现代管理方法，强调员工参与目标制定。根据上述定义，下列属于目标管理的是","options":["公司组织各级员工共同商定年度目标，定期对照目标评估成果并反馈改进","经理每天巡视车间，监督员工按操作规程作业","公司按出勤天数给员工计发工资","主管临时布置任务，要求员工下班前完成并汇报"],"answer":0,"explanation":"员工参与目标制定、以成果为标准、定期对照评估反馈，是目标管理的完整闭环。B项是过程监督，C项是考勤计酬，D项是临时任务布置，均不符合员工参与和目标导向的特征。故本题选A。判断推理300题·听课讲义·第65页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-031","module":"panduan","prompt":"意思表示是行为能力适格者将意欲实现的民事法律效果发表出来的行为，是民事法律行为的核心要素。根据上述定义，下列构成意思表示的是","options":["钱某做梦时大喊把房子卖了","李某失眠时独自在日记里写下想换工作的念头","赵某在朋友聚餐时开玩笑说真想买下这家餐厅","王某向二手房卖家明确提出以300万元购买该房"],"answer":3,"explanation":"将意欲实现的民事法律效果（购买房屋）向相对人明确发表，构成要约性质的意思表示。B项日记是内心思想，未对外发表；C项是戏谑表示，无意受其拘束，不产生民事法律效果；A项梦中呓语无行为能力承载。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-032","module":"panduan","prompt":"替代性强化是班杜拉社会学习理论的概念，指观察者因看到榜样受强化而受到的间接强化。根据上述定义，下列属于替代性强化的是","options":["小强在家长鼓励下坚持每天晨跑","小刚主动发言受到老师表扬后，发言更加积极","小华看到同学上课讲话被批评，自己也曾在心里默默吐槽老师","小明看到同桌因主动发言受到老师表扬，此后也积极举手发言"],"answer":3,"explanation":"榜样（同桌）受强化（表扬），观察者（小明）受间接强化而改变行为，属于替代性强化。B项是直接强化；C项虽是观察但未产生行为改变，且行为方向与榜样受罚不对应；A项是直接鼓励。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-033","module":"panduan","prompt":"正当防卫是指为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而对不法侵害人采取的制止行为。根据上述定义，下列构成正当防卫的是","options":["持刀歹徒正在行凶时，被害人夺刀反刺致其重伤倒地停止侵害","与邻居积怨已久的老刘趁其不备将其打伤，声称是为防其日后报复","小偷行窃得手离开三天后，失主找到并将其打伤夺回财物","程某误以为路人伸手要打自己，率先将其打倒，实则对方只是挥手打招呼"],"answer":0,"explanation":"针对正在进行的不法侵害实施制止行为，成立正当防卫。B项侵害并非正在进行（假想未来报复），属于事前防卫；C项侵害已经结束，属于事后报复；D项不存在真实的不法侵害，是假想防卫，不构成正当防卫。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-034","module":"panduan","prompt":"市场细分是指营销者通过市场调研，依据消费者的需要和欲望、购买行为和购买习惯等方面的差异，把某一产品的市场整体划分为若干消费者群的市场分类过程。根据上述定义，下列属于市场细分的是","options":["某车企按不同国家设立海外办事处","某超市把商品按食品、日用品、电器分区陈列","某乳企按年龄和消费习惯，把牛奶市场划分为儿童奶、健身奶和中老年高钙奶三类目标群","某公司按部门职能将员工分为研发、销售和后勤"],"answer":2,"explanation":"依据消费者需求与行为差异划分消费者群，属于市场细分。B项是商品陈列分类，划分对象是商品不是消费者群；A项是区域组织布局；D项是内部职能分工。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-035","module":"panduan","prompt":"无因管理是指没有法定或约定的义务，为避免他人利益受损失而管理他人事务的行为。根据上述定义，下列构成无因管理的是","options":["邻居外出数月，老周见其房屋漏雨，主动雇人修缮，防止损失扩大","小郑受朋友委托，在其出差期间帮忙照看宠物狗","物业按物业服务合同对小区绿化进行养护","志愿者受慈善组织指派参与赈灾物资搬运"],"answer":0,"explanation":"无法定或约定义务，为避免邻居利益受损而主动管理其事务（修缮房屋），构成无因管理。B项有委托（约定义务）；C项有合同义务；D项有组织指派的义务来源。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-036","module":"panduan","prompt":"路径依赖是指人们一旦选择了某一路径，惯性的力量会使这一选择不断自我强化，难以轻易走出去。根据上述定义，下列属于路径依赖的是","options":["小李尝试多种学习方法后选择了最适合自己的错题集法","某公司根据市场变化，果断放弃原有产品线转向新赛道","某厂长期使用某套老旧生产系统，虽效率低下，但因全员熟练和改造成本高，一直沿用","某市在专家论证后修订了城市轨道交通规划"],"answer":2,"explanation":"既有选择因惯性不断自我强化（熟练度、转换成本），即使低效也难以改变，是路径依赖。B项主动摆脱旧路径；A项是理性选择过程；D项是规划的动态优化。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-037","module":"panduan","prompt":"诽谤罪是指故意捏造并散布虚构的事实，足以贬损他人人格、破坏他人名誉，情节严重的行为。根据上述定义，下列构成诽谤罪的是","options":["周某误听传言转述他人受贿，后经查证不实，他立即删帖澄清","钱某目睹孙某当众打人，如实描述经过并发布到网上","李某当众辱骂邻居，用词粗鄙但未捏造事实","赵某凭空编造同事贪污公款的虚假材料并在网上大量散布，致其精神失常"],"answer":3,"explanation":"捏造虚假事实并散布，足以贬损人格、情节严重，构成诽谤罪。B项如实描述，不虚构；C项是辱骂，无捏造事实，属侮辱而非诽谤；A项非故意捏造（误听转述）且及时澄清，无诽谤故意。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-038","module":"panduan","prompt":"经济增加值（EVA）是指企业税后净营业利润扣除全部资本成本后的余额，它衡量的是企业为股东创造的真正价值。根据上述定义，下列企业最有可能具有较高的经济增加值的是","options":["净利润1亿元，但占用资本的机会成本高达1.2亿元","净利润5000万元，占用资本的机会成本为2000万元","净利润2亿元，但全部来自政府一次性补贴","净利润8000万元，另有未入账的环境治理欠账1亿元"],"answer":1,"explanation":"税后利润扣除资本成本后为正（5000万-2000万=3000万），创造了真正价值。A项EVA为负，C项利润依赖一次性补贴、可持续性存疑且仍需扣除资本成本，D项有巨额未入账成本、真实价值被高估。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-039","module":"panduan","prompt":"匿名处理是指在数据发布或共享前，通过技术手段移除或加密能够直接或间接识别特定个人的信息，使数据主体无法被识别或重新识别的过程。根据上述定义，下列属于匿名处理的是","options":["某公司把客户姓名、身份证号完整打包卖给营销公司","某App把用户手机号明文存储在服务器数据库中","某平台将用户浏览记录与其实名账号绑定用于精准推送","医院把病历数据中的姓名替换为随机编码后再提供给科研机构"],"answer":3,"explanation":"以随机编码替换姓名等直接标识，使数据主体无法被直接识别，属于匿名处理。B、C、D三项均保留或使用可识别个人的信息，不符合定义。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-040","module":"panduan","prompt":"社会惰化是指个人在与他人共同完成任务时所付出的努力比单独完成时减少的现象。根据上述定义，下列属于社会惰化的是","options":["拔河实验中，多人一组的平均出力明显低于单人拉拽时的出力","运动员在接力赛中奋力冲刺，成绩好于个人赛","小方独自复习时效率很低，加入学习小组后效率提高","合唱队为追求整齐效果，各声部严格按指挥要求控制音量"],"answer":0,"explanation":"共同任务时个体努力下降，是社会惰化的经典实验表现。B项是社会助长（他人在场提升表现），C项是群体促进学习效率，D项是任务要求的协调行为而非努力减少。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-041","module":"panduan","prompt":"居住权是指对他人所有的住宅享有占有、使用的用益物权，以满足生活居住的需要。根据上述定义，下列设立居住权的是","options":["公司为员工提供宿舍并收取水电费","房东将房屋出租给租客，约定租期两年","小潘借款时把房产证押在出借人手中","老徐立遗嘱为再婚配偶在其名下房屋上设立长期居住的权利，并在登记机构办理登记"],"answer":3,"explanation":"为满足生活居住需要，在他人住宅上设立占有、使用的用益物权并经登记，属于居住权。B项是租赁债权；C项是转移占有的担保做法（押证件不产生物权）；A项是单位福利安排，未设立物权。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-042","module":"panduan","prompt":"蔡格尼克效应是指人们对未完成的工作比已完成的工作记忆更深刻的心理现象。根据上述定义，下列属于蔡格尼克效应的是","options":["小王对三年前的一次成功演讲记忆犹新","小李习惯用清单记录待办事项，完成后逐项划掉","老师强调复习已学内容可以巩固记忆","追剧到一半被迫中断的人，对剧情细节念念不忘，比看完大结局的记得更牢"],"answer":3,"explanation":"未完成的任务比已完成的记得更牢，正是蔡格尼克效应。B项是任务管理习惯，C项是复习巩固的一般规律，A项是已完成且深刻的事件记忆，均不符合未完成优势。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-043","module":"panduan","prompt":"公共利益是指不特定的社会成员所共同享有的利益，具有共享性和不可分割性。根据上述定义，下列最接近公共利益的是","options":["某企业对其注册商标的专用权","某小区业主对专属车位的使用权","城市防洪大堤的保护","某村委会对本村集体土地的发包收益"],"answer":2,"explanation":"防洪大堤保护的是不特定多数社会成员的共同安全利益，具有共享性、不可分割性，最接近公共利益。B项专属车位是特定人的私益，A项商标权是私权，D项集体收益归于特定集体成员。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-044","module":"panduan","prompt":"从众是指个体在群体压力下，改变自己的初始态度和行为，采取与多数人一致行为的现象。根据上述定义，下列属于从众的是","options":["小方经过对两所大学的认真比较，选择了同学也选择的那所","小周本打算报法学专业，见全班同学都报计算机，便也改报了计算机","交警按信号灯指示通行","评审会上，专家各自独立填写评分表后统一回收汇总"],"answer":1,"explanation":"在群体压力下改变初始态度与多数人保持一致，是从众。A项是独立判断后的巧合选择，C项是规则遵从，D项是独立评价程序。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-045","module":"panduan","prompt":"行政裁决是指行政机关依照法律授权，对发生在行政管理活动中的平等主体间的特定民事争议进行审查并作出裁决的行政行为。根据上述定义，下列属于行政裁决的是","options":["法院对两公司的合同纠纷作出一审判决","市监局对某公司超范围经营作出责令改正的处罚","县政府对甲、乙两家企业间的土地权属争议依法作出处理决定","居委会调解邻里间的装修噪音纠纷，促成和解"],"answer":2,"explanation":"行政机关依授权对平等主体间的民事争议（土地权属）作出裁决，属于行政裁决。B项是行政处罚（管理相对人，非平等主体间民事争议）；A项是司法裁判；D项是人民调解，无强制裁决。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-046","module":"panduan","prompt":"认知失调是指当个体的行为与其态度不一致，或同时持有两个相互矛盾的认知时产生的心理不适感，个体往往会通过改变认知或行为来消除失调。根据上述定义，下列属于通过改变行为消除认知失调的是","options":["觉得读书重要却很少读书的小林，安慰自己工作太忙没时间","抽烟的老郑说：我爷爷抽了一辈子烟也活到九十岁","明知熬夜有害却天天熬夜的小吴，开始强制自己按时入睡","重视环保的小方买了大排量汽车后，表示油耗高才有驾驶乐趣"],"answer":2,"explanation":"改变行为（按时入睡）使之与认知（熬夜有害）一致，属于通过改变行为消除失调。B、C、D三项都是通过改变认知（找理由、合理化）来消除失调。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-047","module":"panduan","prompt":"继承恢复请求权是指继承权受到侵害时，继承人享有的请求恢复其继承原状的权利。根据上述定义，下列行使继承恢复请求权的是","options":["债权人在债务人死亡后，起诉要求以遗产清偿债务","遗嘱继承人放弃继承后，遗产按法定继承分配","长子擅自独占父母遗留的房产，其他继承人起诉要求分割遗产","受遗赠人在知道受遗赠后六十日内作出接受的表示"],"answer":2,"explanation":"继承权被侵害（遗产被独占），请求恢复继承原状（分割遗产），属于继承恢复请求权。B项是放弃继承的正常流程，A项是债权人的债权请求，D项是受遗赠的接受表示，均非继承权受侵害后的恢复请求。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-048","module":"panduan","prompt":"标签理论认为，越轨行为是社会互动中被他人贴上越轨者标签的结果，标签会强化越轨者的自我认同并促成更多越轨行为。根据上述定义，下列做法最符合标签理论视角的是","options":["学校为全体学生建立统一的行为规范手册","老师对逃课学生家访沟通，共同制定改进计划并予以正向激励","公安机关依法对屡次违法者实施治安处罚","学校给偶尔逃课的学生冠以差生称号，此后该生逃课愈发频繁"],"answer":3,"explanation":"贴上差生标签强化其越轨自我认同、诱发更多越轨行为，是标签理论的核心机制。B项是正向干预，C项是依法惩戒，A项是普遍规范管理，均未体现标签的负面建构作用。故本题选D。判断推理300题·听课讲义·第66页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-049","module":"panduan","prompt":"搭便车是指在集体行动中，成员不付出成本或很少付出成本，却坐享他人努力所带来的成果的行为。根据上述定义，下列属于搭便车的是","options":["业委会筹资加装电梯，个别业主既不出钱不出力，完工后照常使用","小区业主大会经表决通过统一更换物业的决定","某企业联合同行研发新技术，按约定比例分担研发费用","志愿者清理河道垃圾，沿岸居民送水致谢"],"answer":0,"explanation":"不付出成本却享受集体成果，是搭便车。B项是集体决策，C项是按约分担成本的联合行动，D项沿岸居民未付出成本但也未刻意坐享成果（致谢属情感回应，且清理志愿服务本就面向公益）。相比之下A项完全符合不劳而获的定义要件。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-050","module":"panduan","prompt":"行政给付又称行政物质帮助，是指行政机关依法对特定相对人给予物质上帮助的行政行为。根据上述定义，下列属于行政给付的是","options":["民政部门依法向特困人员发放供养金并安排入住福利机构","税务机关依法向符合条件的企业办理出口退税","人社部门向失业人员发放失业保险金","财政部门按预算向公办学校拨付教育经费"],"answer":0,"explanation":"行政机关依法对特定相对人（特困人员）给予物质帮助，属于行政给付。B项是退税（税收征管行为），C项失业保险金属于社会保险待遇的给付——注：失业保险由社保经办机构依法发放，性质上是社保待遇而非行政机关的行政物质帮助；D项是内部财政预算拨款，相对人非特定行政相对人个人。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-051","module":"panduan","prompt":"平台经济是指以互联网平台为依托，整合多边市场资源，促成多方交易并从中获取收益的经济形态。根据上述定义，下列属于平台经济的是","options":["某餐馆自建小程序，仅向到店顾客销售自家菜品","某外卖平台撮合餐馆与消费者交易，按订单抽取技术服务费","某服装厂通过批发商将产品分销至各地门店","某小区团购群群主义务为邻居代购生鲜，不收取任何费用"],"answer":1,"explanation":"互联网平台整合多边资源、促成多方交易并从中获益（抽成），符合平台经济定义。A项是单边自营；C项是传统分销渠道；D项虽依托网络社群但未形成经营性平台且不获取收益。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-052","module":"panduan","prompt":"逆映射思维是指在解决问题时，不直接从正面突破，而是从结论或对立面出发倒推条件的思维方式。根据上述定义，下列运用逆映射思维的是","options":["设计师参考行业通行样式，直接产出新的设计方案","工程师先确定产品必须满足的性能终点，再倒推各环节的技术参数","质检员按清单逐项核对产品的合格指标","采购员按历年用量估算下季度原料采购量"],"answer":1,"explanation":"从结论（性能终点）出发倒推条件（技术参数），是逆映射思维。A项是经验借鉴，C项是正向核对，D项是基于历史数据的正向预测。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-053","module":"panduan","prompt":"集体记忆是指一个群体共同保存的对过去的记忆，它通过仪式、文本、纪念物等载体在群体内部传承，并塑造群体认同。根据上述定义，下列属于集体记忆载体发挥作用的是","options":["历史学者在期刊上发表一篇考证详实的论文","某市每年在抗战纪念日组织市民参观纪念馆并举行公祭仪式","某人在家庭相册里翻看自己童年的照片","某公司为新员工建立人事档案"],"answer":1,"explanation":"纪念日仪式与纪念馆作为载体在群体（市民）内部传承共同记忆并塑造认同，符合集体记忆。A项是学术研究，C项是个体记忆，D项是行政管理文书。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-054","module":"panduan","prompt":"差额选举是指候选人名额多于应选名额的选举方式，与之相对的是等额选举。根据上述定义，下列属于差额选举的是","options":["某协会章程规定理事候选人12名，应选理事9名，会员投票选出9名","某单位推荐1名候选人竞选1个职位，全体表决通过","某村委会主任职位只有1名候选人，村民投赞成或反对票","某公司董事会按出资比例直接确定董事人选"],"answer":0,"explanation":"候选人名额（12）多于应选名额（9），供选民选择，属于差额选举。B、C项候选人数等于应选名额，是等额选举；D项按比例确定，无选举竞争。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-055","module":"panduan","prompt":"文化堕距（文化滞后）是指物质文化与非物质文化（观念、制度等）在变迁速度上不一致，非物质文化往往滞后于物质文化的现象。根据上述定义，下列体现文化堕距的是","options":["移动支付技术迅速普及，而部分领域现行监管规则仍沿用现金时代的框架","某地传统民居从土木结构更新为钢筋混凝土结构","某企业更新了全部生产设备，产能翻番","某高校新图书馆落成，藏书量大幅增加"],"answer":0,"explanation":"物质层面（支付技术）快速变迁，观念与制度层面（监管规则）滞后，符合文化堕距。B、C、D项均为物质文化自身的更新，不涉及非物质文化的滞后。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-056","module":"panduan","prompt":"情势变更是指合同成立后，合同的基础条件发生了当事人在订立合同时无法预见的、不属于商业风险的重大变化，继续履行合同对一方明显不公平，受不利影响的当事人可请求重新协商或变更、解除合同。根据上述定义，下列适用情势变更的是","options":["卖方为追逐更高利润，主动毁约把货卖给出价更高的第三方","经销商囤货后市场价格正常下跌，导致利润缩水","买方因经营不善资金紧张，无力按期付款","合同履行前，标的物产地突发百年一遇地震，导致供货成本暴涨数倍且无法预见"],"answer":3,"explanation":"无法预见的重大变化（百年一遇地震）导致履行显失公平，适用情势变更。B项是正常商业风险，C项是自身履约能力问题，A项是主动违约，均不属于情势变更。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-057","module":"panduan","prompt":"投射是指个体将自己不被接受的心理特征或冲动归因到他人身上的心理防御机制。根据上述定义，下列属于投射的是","options":["考试失利后，小杜把失败归因于题目出得太偏","自己有较强的竞争敌意，却总认为别人处处针对他","小何把对父亲的敬爱之情转移到恩师身上","小蒋心里焦虑却向朋友表现出轻松愉快的样子"],"answer":1,"explanation":"将自身不被接受的敌意归因于他人，是投射。A项是外归因（合理化的一种），C项是置换（转移），D项是反向形成或掩饰，均非投射。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-058","module":"panduan","prompt":"非物质文化遗产是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，以及与之相关的实物和场所。根据上述定义，下列属于非物质文化遗产的是","options":["世代相传的传统戏曲的表演技艺及其经典剧目","出土的战国青铜编钟本体","明代书画真迹原件","考古遗址的出土建筑遗存"],"answer":0,"explanation":"世代相传的表演技艺与剧目属于传统文化表现形式，是非物质文化遗产。B、C、D项均为实物本体，属于物质文化遗产（文物）。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-059","module":"panduan","prompt":"商业秘密是指不为公众所知悉、具有商业价值并经权利人采取相应保密措施的技术信息和经营信息。根据上述定义，下列属于商业秘密的是","options":["企业官网公开发布的产品说明书","已在国家知识产权局公告的发明专利内容","某饮料企业严格保密的配方及加密管理工艺参数","行业内普遍通行的加工操作规范"],"answer":2,"explanation":"不为公众所知悉（严格保密）、有商业价值（配方）、采取保密措施（加密管理），三要件齐备。B项已公告即公开，A项已公开发布，D项属公知公用信息，均不满足不为公众所知悉要件。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-060","module":"panduan","prompt":"拘役与管制都是我国刑罚中的主刑。管制是指对犯罪分子不予关押，但限制其一定自由的刑罚方法；拘役是指短期剥夺犯罪分子人身自由并由公安机关就近关押执行的刑罚方法。根据上述定义，下列判处拘役的情形是","options":["法院对赵某判处罚金2万元","法院判处李某两年刑罚，允许其在社区矫正机构报到并正常生活工作","法院判处王某三个月监禁，由公安机关在看守所就近执行","法院对孙某判处死刑缓期二年执行"],"answer":2,"explanation":"短期剥夺人身自由（三个月）并就近关押执行，符合拘役定义。B项不关押、限制一定自由，是管制；A项罚金是附加刑（财产刑），D项死缓不属于拘役。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-061","module":"panduan","prompt":"注视偏好范式是发展心理学的研究方法，通过记录婴儿对不同刺激的注视时间长短，推断其对刺激的辨别能力与偏好。根据上述定义，下列运用注视偏好范式的是","options":["研究者用问卷量表测量成人的人格特质","研究者记录婴儿听到陌生声音时的心跳变化","研究者观察幼儿在自由游戏中的互动次数","研究者测量婴儿注视人脸图片与几何图形的时长差异，判断其对人脸的偏好"],"answer":3,"explanation":"以注视时间长短作为推断指标，符合注视偏好范式。B项是生理指标测量，C项是行为观察但与注视无关，A项是问卷法。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-062","module":"panduan","prompt":"税收中性原则是指税收征收应尽量不影响市场原有的资源配置格局，不扭曲生产者和消费者的相对价格与选择。根据上述定义，下列税种设计最接近税收中性原则的是","options":["对高污染产品征收环境保护税以引导企业转型","对香烟征收高额消费税以抑制吸烟","对所有商品按统一比例征收的增值税，不同商品间税率差异小","对进口奢侈品征收差别关税保护本国同类产业"],"answer":2,"explanation":"统一比例、税率差异小，对相对价格与选择的扭曲最小，最接近中性。B、A项是矫正性税收，目的正是改变行为、扭曲资源配置；D项差别关税意在引导消费选择。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-063","module":"panduan","prompt":"公司治理中的独立董事制度是指上市公司董事会中设置的不在公司担任除董事外的其他职务，且不受主要股东、实际控制人影响的董事，以保护中小股东权益、监督公司运作。根据上述定义，下列最有可能属于独立董事的是","options":["公司财务负责人","公司总经理兼任的董事","控股股东委派到董事会的代表","受聘担任上市公司董事的经济学教授，未持有该公司股份，也不在公司任职"],"answer":3,"explanation":"不在公司任职、不受主要股东影响的外部专业人士，符合独立性要求。B、A项在公司担任高管职务，C项受控股股东委派，均缺乏独立性。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-064","module":"panduan","prompt":"反垄断法中的相关市场是指经营者在一定时期内就特定商品或者服务进行竞争的商品范围和地域范围。界定相关市场通常需要考虑需求替代与供给替代。根据上述定义，下列界定相关市场的方式最合理的是","options":["以行政区划的边界机械地划分商品竞争地域","以目标商品的品牌数量多少为唯一依据划定市场","以经营者的注册资本大小划分市场范围","以消费者能否方便地用其他商品替代目标商品、替代程度如何为依据划定竞争范围"],"answer":3,"explanation":"需求替代分析（能否方便替代、替代程度）是界定相关市场的核心方法。B项品牌数量、C项注册资本均与竞争关系无直接对应，A项机械按行政边界划分忽视了实际竞争辐射范围。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-065","module":"panduan","prompt":"表见代理是指行为人虽无代理权，但因存在使相对人合理相信其有代理权的外观（如持有盖章的空白合同书），相对人善意无过失地与之实施法律行为，法律后果由被代理人承担的制度。根据上述定义，下列构成表见代理的是","options":["李某离职后仍持有公司未收回的盖章空白合同书，与不知情的客户签约，客户有理由相信其有代理权","王某伪造某公司公章冒充业务员签约，该公司对此毫无可归责之处且客户未核实身份","张某经公司正式授权与客户签订采购合同","赵某在公司明确登报声明其代理权终止后，仍以公司名义与知情客户签约"],"answer":0,"explanation":"存在代理权外观（未收回的盖章空白合同书）且相对人善意无过失，构成表见代理。B项外观由伪造产生且公司无可归责性，客户未尽注意义务，不符合善意无过失要件；C项是有权代理；D项公司已公示授权终止，客户明知，不构成合理信赖。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-066","module":"panduan","prompt":"沉没成本谬误之外的承诺升级是指决策者在项目出现负面反馈后，不仅不减少投入，反而追加资源以证明先前决策正确的倾向。根据上述定义，下列属于承诺升级的是","options":["研发项目评估通过后，公司按原计划追加第二期预算","研发项目中期评估不及预期，负责人申请追加预算，声称再投入就能成功","项目失败后公司成立复盘小组，总结教训并终止项目","投资人依市场数据定期调整投资组合的配置比例"],"answer":1,"explanation":"负面反馈后不减投反加投，以证明先前决策正确，属于承诺升级。A项是计划内的正常推进，C项是及时止损，D项是数据驱动的动态调整。故本题选B。判断推理300题·听课讲义·第67页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-067","module":"panduan","prompt":"证明责任（举证责任）是指当事人对自己提出的主张有提供证据加以证明，以及事实真伪不明时承担不利后果的责任。根据上述定义，下列关于证明责任的情形描述正确的是","options":["原告主张被告违约，若双方均无法举证致事实真伪不明，由原告承担不利后果","被告对原告的主张保持沉默，原告因此免除举证义务","法院主动代替原告收集全部证据并承担举证不能的后果","主张方只要提出主张即视为完成证明责任"],"answer":0,"explanation":"主张者举证、真伪不明时由主张方承担不利后果，符合证明责任分配的基本法理。B项沉默不免除原告举证义务，C项法院不承担举证责任，D项提出主张不等于完成证明。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-068","module":"panduan","prompt":"代际公平是指当代人在利用资源和环境时，应当保证后代人享有与当代人同等的发展机会和资源条件。根据上述定义，下列违反代际公平的是","options":["某企业投资研发可降解材料以减少白色污染","某市推行垃圾分类以促进资源循环利用","某国立法规定渔业捕捞须保持种群可持续数量","某地过度开采地下水导致地下水位持续下降，后代将无水可用"],"answer":3,"explanation":"透支后代赖以生存的资源，剥夺其后代同等的发展条件，违反代际公平。B、C、A项均是有利于后代可持续发展的做法。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-069","module":"panduan","prompt":"印象管理是指人们试图控制他人对自己形成印象的过程，包括自我呈现的策略性行为。根据上述定义，下列属于印象管理的是","options":["小唐在朋友圈如实记录自己的日常心情","求职者在面试中着装正式、主动展示与岗位匹配的成功项目经历","审计人员按规定披露审计过程与结论","某公司按监管要求公开年度财务报告"],"answer":1,"explanation":"策略性地控制他人对自己的印象（着装、选择性展示），属于印象管理。A项是如实记录而非策略性控制，C、D项是法定信息披露义务。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-070","module":"panduan","prompt":"疏忽大意的过失是指行为人应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，以致发生这种结果的心理状态。根据上述定义，下列属于疏忽大意的过失的是","options":["工人故意破坏安全装置导致事故发生","猎人明知前方有人仍朝其方向开枪，致人伤亡","司机因突发心脏病失去意识导致车辆失控撞人","护林员按规巡查时，未注意到烟头引燃的暗火，导致山林大火"],"answer":3,"explanation":"应当预见（职业注意义务）而疏忽未预见致危害发生，属于疏忽大意的过失。B项明知而放任，是故意；C项无预见可能性，属意外事件；A项是直接故意。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-071","module":"panduan","prompt":"电子商务平台经营者是指为交易双方或多方提供网络经营场所、交易撮合、信息发布等服务，供交易双方或多方独立开展交易活动的自然人、法人和其他组织。根据上述定义，下列属于电子商务平台经营者的是","options":["在自建官网直销自家服装的服装公司","运营某二手交易网站，为买卖双方提供信息发布与交易撮合服务的科技公司","通过直播销售自家农产品的农户","为自家餐饮门店提供外卖接单服务的个体店主"],"answer":1,"explanation":"为交易多方提供场所、撮合与信息服务，供其独立交易，符合平台经营者定义。B、C、D项均为自营卖家，不提供第三方交易撮合服务。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-072","module":"panduan","prompt":"酝酿效应是指当个体反复思考某一问题而不得解时，暂时搁置问题，休整后重新面对时反而更容易找到解决办法的现象。根据上述定义，下列属于酝酿效应的是","options":["小郑按部就班完成实验，顺利得到预期结果","小孙苦思论文思路三天无果，周末爬山放松后突然灵光一现找到突破口","小钱遇到难题立即请教导师，当场获得指导","小冯通过穷举所有选项逐一验证得到了答案"],"answer":1,"explanation":"搁置休整后重新面对更易解决，是酝酿效应。A项无搁置过程，C项借助外部帮助，D项是系统性穷举，均非酝酿效应。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-073","module":"panduan","prompt":"留置送达是指受送达人拒绝接收诉讼文书时，送达人依法把文书留在受送达人处所的送达方式。根据上述定义，下列属于留置送达的是","options":["法院通过电子诉讼平台向被告的确认手机号推送电子文书","法院工作人员向被告出示并宣读判决书，被告拒收，工作人员将文书留在其住所并拍照记录见证","法院将文书邮寄至被告的经常居住地","法院在报纸上刊登公告送达文书"],"answer":1,"explanation":"受送达人拒收时依法将文书留置于其住所，属于留置送达。A项是电子送达，C项是邮寄送达，D项是公告送达。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-074","module":"panduan","prompt":"机会公平是指人们在同样的规则和条件下竞争，起点和过程不受身份、财富等先赋因素的不当影响。根据上述定义，下列违背机会公平的是","options":["某岗位招聘以父母的户籍作为隐性筛选条件，不面向外地候选人开放","某竞赛面向所有符合资格的选手开放报名并统一命题统一评审","某高校按统一分数线择优录取考生","某企业通过公开笔试和结构化面试选拔员工"],"answer":0,"explanation":"以先赋性因素（父母户籍）设置不当门槛，排斥平等竞争机会，违背机会公平。B、C、D项均为统一规则下的公平竞争安排。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-075","module":"panduan","prompt":"功能固着是指个体只看到事物的通常功能，而看不到其其他潜在功能的思维局限。根据上述定义，下列体现克服功能固着的是","options":["小陈没有螺丝刀时，想到用硬币边缘拧开螺丝","小钱用订书机装订试卷","小冯用钢笔在纸上写字","小蒋用锅煮饭"],"answer":0,"explanation":"硬币的常规功能是货币，将其用作拧螺丝的工具，突破了常规功能的认知，是克服功能固着。B、C、D项均是按常规功能使用物品。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-076","module":"panduan","prompt":"无过错责任是指不论行为人有无过错，法律规定应当承担侵权责任的，依其规定承担责任的归责原则。根据上述定义，下列适用无过错责任的是","options":["司机酒后驾车撞伤行人承担赔偿责任","邻居因疏忽大意砸坏他人窗户承担赔偿责任","某化工厂依法排放达标仍因化学品泄漏污染周边农田，依法对农户损失承担赔偿责任","网店发错货物向买家承担违约责任"],"answer":2,"explanation":"即使排放达标、无过错，依法仍须对高危污染损害担责，属于无过错责任。B项以过错（疏忽）为前提，A项有明显过错，D项是违约责任（严格责任语境不同，且以合同为基础，不如C项贴合侵权归责的无过错责任）。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-077","module":"panduan","prompt":"数据画像是指通过收集、分析用户的属性与行为数据，为其建立标签化信息模型，以描述用户特征和预测其偏好的做法。根据上述定义，下列属于数据画像的是","options":["商场在门口发放纸质问卷统计客流量","客服在通话中手工记录该客户本次咨询的问题","学校按班级统计本学期平均出勤率","平台根据用户浏览、下单、搜索记录为用户贴上母婴偏好、价格敏感等标签并推荐商品"],"answer":3,"explanation":"基于行为数据建立标签化模型并预测偏好，符合数据画像。B项是单次人工记录，C项是统计汇总，A项是一次性调查，均未形成个体标签模型。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-078","module":"panduan","prompt":"社区照顾是指动员社区资源，运用非正式支持网络，为有需要的人士在家庭或社区中提供照顾服务，使其尽可能维持在熟悉的环境中生活的模式。根据上述定义，下列属于社区照顾的是","options":["街道组织志愿者与独居老人结对，定期上门探访并提供助餐助洁服务","市政府新建一座大型专业养老院集中收治老人","家属将失能老人送入异地收费疗养机构长期住院","医院为住院患者提供全天候临床护理"],"answer":0,"explanation":"依托社区资源与非正式网络（志愿者结对），让照顾对象在熟悉的社区环境中生活，符合社区照顾。B、C项是机构照顾，D项是医院临床护理。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-079","module":"panduan","prompt":"自我服务偏差是指个体把成功归因于自己的能力和努力，而把失败归因于外部因素的倾向。根据上述定义，下列属于自我服务偏差的是","options":["小孟把项目成功归功于自己的领导力，把项目延期归咎于客户反复改需求","小唐客观分析项目得失，认为成功得益于团队配合，失败源于自身估算失误","小何把考满分归功于运气好","小潘把比赛失利完全归咎于自己的训练不足"],"answer":0,"explanation":"成功归于内（自己的能力）、失败归于外（客户），是典型的自我服务偏差。B项是客观归因，C项成功归外、D项失败归内，方向均与该偏差相反。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-080","module":"panduan","prompt":"如果某项制度规定：行政机关作出对当事人不利的决定前，应当听取当事人的陈述和申辩。这一制度体现的程序价值是","options":["高效便民","程序正当","权责统一","诚实守信"],"answer":1,"explanation":"不利决定前听取陈述申辩，保障相对人参与和抗辩权，是程序正当原则的核心要求。A项强调便捷服务，C项强调责任承担，D项强调信赖保护，均非该制度的直接价值。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-081","module":"panduan","prompt":"认知重评是指个体通过改变对情绪事件的理解和评价来调节情绪反应的策略。根据上述定义，下列属于认知重评的是","options":["小齐难过时躲进房间独自哭泣宣泄","小韩紧张时反复做深呼吸放松肌肉","小秦把落选演讲比赛理解为锻炼机会与查漏窗口，紧张感随之明显缓解","小范心烦时出门跑步转移注意力"],"answer":2,"explanation":"改变对事件的理解与评价（重新诠释落选的意义）来调节情绪，属于认知重评。B项是生理放松调节，A项是情绪宣泄，D项是注意转移，均不改变认知评价。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-082","module":"panduan","prompt":"沉锚效应是指人们在做判断时，容易受最先接触到的信息（锚）的影响，使估计值向锚的方向偏移。根据上述定义，下列利用沉锚效应的是","options":["商家先标出虚高的原价，再打五折促销，顾客觉得实惠","商家按成本加成定价，明码标价出售商品","消费者货比三家后按性价比选购商品","平台按历史成交价自动生成价格曲线供参考"],"answer":0,"explanation":"先设置的虚高原价成为锚，使顾客的估值向上偏移、感知折扣更划算，是沉锚效应的运用。B项是成本定价，C项是理性比较，D项是数据参考工具。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-083","module":"panduan","prompt":"行政征收是指行政机关依照法律规定，以强制方式无偿取得相对人财产所有权的行为；行政征用是指行政机关依照法律规定，有偿使用相对人财产的行为。根据上述定义，下列属于行政征用的是","options":["国家依法征收集体土地并支付土地补偿费后将土地转为国有","税务机关依法向企业征收企业所得税","防汛期间，县政府临时征用一批民用货车运输抢险物资并支付使用补偿","海关依法对进境物品征收关税"],"answer":2,"explanation":"临时有偿使用相对人财产（车辆），用后归还并补偿，属于行政征用。B、D项是无偿取得货币（税费），属于行政征收中的税收征收；A项征收集体土地是所有权的转移（无偿性体现为征收后的补偿属于法定补偿性质，土地所有权已变更），通说认为属于征收而非征用。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-084","module":"panduan","prompt":"视觉暂留是指光刺激停止后，视觉印象仍保留短暂时间的现象。根据上述定义，下列利用视觉暂留原理的是","options":["近视者佩戴眼镜后视物清晰","放大镜把文字放大便于阅读","逐帧播放的动画在屏幕上呈现出连续运动的画面","舞台追光灯随演员移动照亮其身影"],"answer":2,"explanation":"静止帧快速切换时，前一帧的视觉印象短暂保留，与后一帧融合形成连续运动感，利用的是视觉暂留。B项是光学放大，A项是屈光矫正，D项是照明控制。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-085","module":"panduan","prompt":"不可抗辩条款是指人身保险合同成立超过一定期限后，保险人不得以投保人在投保时未如实告知为由解除合同并拒绝赔付的规则。根据上述定义，下列保险公司依不可抗辩条款不得解除合同的是","options":["投保人虚构保险标的骗取保险金，合同自始无效","合同成立三个月，保险人发现投保时未告知重大病史而解除合同","人身保险合同成立已满两年，保险人发现投保人投保时隐瞒病史，主张解除合同","被保险人在合同成立一年后故意制造保险事故骗赔"],"answer":2,"explanation":"合同成立超过法定期限（两年）后，即使存在未如实告知，保险人也不得解除合同，C项符合。B项在期限内，保险人可依法解除；A项合同自始无效不适用该条款；D项是骗保欺诈情形，不适用不可抗辩保护。故本题选C。判断推理300题·听课讲义·第68页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-086","module":"panduan","prompt":"寄居效应（旁观者效应）是指在紧急情况下，在场人数越多，个体施救的可能性反而越低的现象。根据上述定义，下列符合旁观者效应的是","options":["街头有人晕倒，围观者众多却人人观望，无人第一时间施救","只有路过的护士一人发现有人晕倒，立即上前施救","消防员接到报警后迅速赶到现场灭火","某小区业主自发组建巡逻队轮流值夜"],"answer":0,"explanation":"在场人数多、责任分散导致无人施救，是旁观者效应。B项单人在场即时施救恰是对照情形，C项是职责履行，D项是主动协作。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-087","module":"panduan","prompt":"行政强制执行是指在当事人不履行行政决定所确定的义务时，行政机关或人民法院依法强制其履行义务或达到与履行义务相同状态的制度。根据上述定义，下列属于行政强制执行的是","options":["环保部门对超标排污企业责令限期整改","交警对违法停放的车辆粘贴告知单","企业逾期不缴纳罚款，法院依申请冻结并划拨其银行存款","市场监管部门对涉嫌违法的企业立案调查"],"answer":2,"explanation":"义务人不履行义务时依法强制实现义务内容（划拨存款抵缴罚款），属于行政强制执行。B项是告知行为，A项是行政命令，D项是调查程序。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-088","module":"panduan","prompt":"镜像神经元是指个体在执行某一动作和观察他人执行相同动作时都会被激活的神经元，被认为是理解他人行为意图的神经基础之一。根据上述定义，下列现象最能支持镜像神经元功能的是","options":["闻到食物香味时，观察者分泌唾液","看到红色时，观察者的视觉皮层被激活","听到巨大声响时，观察者出现惊跳反射","看到别人被纸片割伤手指时，观察者的大脑运动区出现与自身执行同类动作相似的激活"],"answer":3,"explanation":"观察他人动作时，运动区出现与执行动作相似的激活，正是镜像机制的表现。B项是一般视知觉，C项是反射，A项是条件性生理反应，均与动作镜像无关。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-089","module":"panduan","prompt":"食品安全标准应当以保障公众身体健康为宗旨，做到科学合理、安全可靠。下列关于食品安全标准的说法中，符合其制定宗旨的做法是","options":["根据风险评估结果，对某类食品添加剂设定严格的限量标准","为保护本地企业，对本地与外地同类食品设定不同安全限量","企业自行制定低于国家标准强制要求的企业内控标准并对外宣称其为地方标准","照搬外国标准而不考虑本国居民膳食暴露差异"],"answer":0,"explanation":"基于风险评估设定严格限量，正是以保障公众健康为宗旨的科学做法。B项地方保护违背公平与科学，C项冒充标准涉嫌违规，D项脱离本国实际。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-090","module":"panduan","prompt":"成就动机是指个体追求自认为重要的、有价值的工作，并使之达到完美状态的动机，分为力求成功与避免失败两种倾向。根据上述定义，下列属于力求成功倾向占主导的是","options":["小雷只选择有把握的简单任务，回避一切可能失败的机会","小谭主动选择有挑战性的课题，享受攻克难题的成就感，即使失败风险较高","小魏因害怕被批评而勉强参加技能比赛","小潘参赛只为避免垫底名次"],"answer":1,"explanation":"主动追求挑战、以成功与完美为取向，属于力求成功倾向。B、C、D项均以避免失败为核心动机。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-091","module":"panduan","prompt":"行政规划（行政计划）是指行政机关为谋取公共利益，就未来一定时期内所要实现的目标及实现目标的步骤、方法所作的部署与安排。根据上述定义，下列属于行政规划的是","options":["市政府发布未来十年的城市综合交通体系规划并明确各阶段建设目标","市监局对某超市开展食品安全专项检查","教育局对违规招生学校作出警告处分","民政局发放本年度困难群众慰问金"],"answer":0,"explanation":"面向未来的目标部署与步骤安排，符合行政规划。B项是监督检查，C项是行政处罚，D项是行政给付的具体执行。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-092","module":"panduan","prompt":"隐性知识是指难以用语言文字清晰表达、高度个性化、在实践情境中习得的知识；显性知识是能够以编码化形式传递的知识。根据上述定义，下列属于隐性知识的是","options":["老工匠凭手感判断陶坯厚度的技艺，只能通过长期带教言传身授","设备的标准操作手册","化学元素的周期表数据","公司发布的报销流程文件"],"answer":0,"explanation":"难以言传、高度依赖实践情境与个人经验，属于隐性知识。B、C、D项均可编码化传递，属于显性知识。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-093","module":"panduan","prompt":"债务加入是指第三人与债务人约定加入债务并通知债权人，或第三人向债权人表示愿意加入债务，债权人未在合理期限内明确拒绝的，第三人与债务人共同承担债务的行为。根据上述定义，下列构成债务加入的是","options":["好友受债务人委托代为转交还款，但明确表示自己不承担债务","好友仅为债务人的欠款提供房产抵押担保","好友向债权人书面承诺与债务人共同还款，债权人收到后未表示反对","好友建议债权人向债务人催收并提供了线索"],"answer":2,"explanation":"第三人向债权人表示愿意加入债务、债权人未拒绝，与债务人共同承担债务，构成债务加入。B项是担保物权（抵押），A项是单纯履行辅助且明确排除债务承担，D项仅是建议协助。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-094","module":"panduan","prompt":"心理韧性（心理弹性）是指个体面对逆境、创伤等重大压力时的良好适应能力，表现为从挫折中恢复并积极发展的动态过程。根据上述定义，下列体现心理韧性的是","options":["小冯把失败归咎于命运不济，从此一蹶不振","家境优渥的小方学业顺利，未经历重大挫折","小郑遭遇挫折后长期消沉，回避一切社交","破产创业者总结教训后重整旗鼓，两年内再创业并实现盈利"],"answer":3,"explanation":"面对重大逆境良好适应、恢复并积极发展，体现心理韧性。B项未经历逆境（无压力源），C、A项是适应不良。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-095","module":"panduan","prompt":"先占是指以所有的意思占有无主动产而取得其所有权的法律事实。根据上述定义，下列构成先占的是","options":["小候在野外拾取被主人抛弃的旧木箱并搬回家使用","小滕捡到他人遗失的钱包后交至派出所","小万在自己的承包地里发现地下埋藏的文物并据为己有","小卫把邻居误放在自家门口的包裹拆开使用"],"answer":0,"explanation":"以所有的意思占有无主动产（被抛弃的木箱），构成先占。B项是拾得遗失物，须返还；C项文物归国家所有，不属于先占客体；D项是误占有他人动产，非无主物。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-096","module":"panduan","prompt":"反向社会化是指晚辈向长辈传授文化知识和价值观念，长辈向晚辈学习的社会化过程。根据上述定义，下列属于反向社会化的是","options":["退休教师跟着孙辈学习短视频剪辑与线上购物","父亲教儿子骑自行车","学校组织学生参加传统文化研学活动","公司对新员工进行入职文化培训"],"answer":0,"explanation":"晚辈向长辈传授新文化技能，属于反向社会化。B项是正向教养，C、D项是同辈或组织内的传承教育。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-097","module":"panduan","prompt":"善意取得是指无处分权人将动产或不动产转让给受让人，符合法定情形时，受让人取得所有权的制度。根据上述定义，下列适用善意取得的是","options":["小裴以市场价格从不知情的租车人手中购得承租车辆，已交付且支付合理价款，事先不知出租人未授权处分","小从无偿受让了来路不明的手机","小冉明知卖家无权处分仍低价购得盗抢车辆","小裔购得车辆但尚未约定交付与付款事宜"],"answer":0,"explanation":"受让人善意、支付合理价款、完成交付（动产已交付），三要件齐备，适用善意取得。B项无偿受让，C项明知（非善意）且低价，D项未完成交付与价款要件。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-098","module":"panduan","prompt":"破窗效应之外的首属群体是指成员间有面对面的亲密交往和情感联系的群体，如家庭、邻里、朋友群；次属群体则是以间接联系、制度化为特征的功能性群体。根据上述定义，下列属于首属群体的是","options":["每周固定聚会的大学同宿舍好友圈","某行业协会的全体注册会员","某上市公司的全体股东","某市驾照持有人群体"],"answer":0,"explanation":"面对面亲密交往、情感联系紧密，属于首属群体。B、C、D项均以制度或身份关系联结，属于次属群体。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-099","module":"panduan","prompt":"职务发明是指执行本单位任务或者主要利用本单位物质技术条件完成的发明创造，其专利申请权依法归单位所有。根据上述定义，下列属于职务发明的是","options":["作家利用业余时间完成的长篇小说手稿","中学教师在暑假期间自费、自行选题完成的与本职工作无关的木工工具改良","退休五年后的老工程师独立完成的与原单位业务无关的小发明","研发工程师在执行公司布置的攻关任务中完成的工艺改进方案"],"answer":3,"explanation":"执行本单位任务完成的发明创造，属于职务发明。B项与本职工作无关且未利用单位资源，C项退休多年且与原单位业务无关，A项是文学作品而非发明创造。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-100","module":"panduan","prompt":"立法听证是指在立法过程中，立法机关就法案涉及的重大问题组织公众代表、利害关系人和专家陈述意见、提供依据的程序制度。根据上述定义，下列属于立法听证的是二、类比推理（第101–200题）","options":["市政府就具体行政处罚个案听取当事人的申辩","市人大常委会就养犬管理条例草案组织养犬人、受害者代表和动物行为专家陈述意见","法院就某案件组织双方当事人质证","某公司就产品召回方案征求客服部门意见"],"answer":1,"explanation":"立法机关就法案组织公众代表、利害关系人、专家陈述意见，符合立法听证。A项是个案执法程序中的申辩，C项是司法质证，D项是企业内部征求意见。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-101","module":"panduan","prompt":"白居易∶《长恨歌》","options":["吴承恩∶《水浒传》","罗贯中∶《西游记》","蒲松龄∶《儒林外史》","曹雪芹∶《红楼梦》"],"answer":3,"explanation":"白居易是《长恨歌》的作者，为作者与作品的对应关系。D项曹雪芹是《红楼梦》作者，对应一致。B项《西游记》作者是吴承恩，C项《儒林外史》作者是吴敬梓，A项《水浒传》作者是施耐庵，对应均错误。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-102","module":"panduan","prompt":"医生∶听诊器","options":["农民∶丰收","法官∶判决","教师∶黑板","司机∶驾照"],"answer":2,"explanation":"听诊器是医生使用的工具，为职业与工具的对应。C项黑板是教师使用的工具，一致。B项判决是行为结果，A项丰收是结果，D项驾照是资格凭证，均非工具。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-103","module":"panduan","prompt":"烧碱∶氢氧化钠","options":["牛奶∶奶牛","钢铁∶金属","冰∶水","食盐∶氯化钠"],"answer":3,"explanation":"烧碱即氢氧化钠，为同一物质的两种称谓（全同关系）。D项食盐的主要成分即氯化钠，属约定俗成的全同对应，一致。B项钢铁是金属材料，为种属关系；C项冰是水的固态形式；A项为来源关系。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-104","module":"panduan","prompt":"鸟∶翅膀","options":["鱼∶鳍","老虎∶森林","书∶图书馆","司机∶方向盘"],"answer":0,"explanation":"翅膀是鸟的身体组成部分。A项鳍是鱼的组成部分，一致。B项森林是老虎的栖息地，C项图书馆是书的集合场所，D项方向盘是使用的工具而非身体部分。故本题选A。判断推理300题·听课讲义·第69页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-105","module":"panduan","prompt":"病入膏肓∶无可救药","options":["画蛇添足∶画龙点睛","举世无双∶独一无二","雪中送炭∶锦上添花","亡羊补牢∶追悔莫及"],"answer":1,"explanation":"病入膏肓与无可救药是近义关系。B项举世无双与独一无二是近义关系，一致。A项为反义对照，C项语境不同，D项亡羊补牢重在及时补救而非后悔。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-106","module":"panduan","prompt":"咳嗽∶感冒","options":["发烧∶感染","律师∶法庭","跑步∶减肥","暴雨∶内涝"],"answer":0,"explanation":"咳嗽可能是感冒的症状，为症状与疾病的或然对应。A项发烧可能是感染的症状，一致。B项为职业与场所，C项是行为与目标，D项暴雨导致内涝是因果而非症状对应。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-107","module":"panduan","prompt":"白天∶黑夜","options":["活着∶死亡","夏天∶冬天","高峰∶低谷","高山∶大海"],"answer":0,"explanation":"白天与黑夜在同一时间维度上非此即彼，为矛盾关系。A项活着与死亡在生命状态上非此即彼，同为矛盾关系，一致。B项夏冬之间有春秋，为反对关系；C项有中间状态；D项是并列事物。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-108","module":"panduan","prompt":"钢板∶标枪","options":["阳光∶温度","木材∶书桌","水汽∶云","种子∶果实"],"answer":1,"explanation":"钢板是制作标枪的原材料，为原材料与成品的对应。B项木材是制作书桌的原材料，一致。A项是因果，C项是凝结转化，D项是发育来源，均非人工制作对应。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-109","module":"panduan","prompt":"法官∶审理∶判决","options":["作家∶出版∶稿费","学生∶考试∶成绩","厨师∶烹饪∶菜肴","演员∶舞台∶掌声"],"answer":2,"explanation":"法官审理后作出判决，为职业、行为与产出成果的对应。C项厨师烹饪后产出菜肴，一致。B项成绩是评价结果，结构不对应；A项出版是出版社的行为；D项舞台是场所、掌声是反馈。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-110","module":"panduan","prompt":"尺子∶厘米","options":["温度计∶摄氏度","钟表∶小时","地图∶城市","相机∶风景"],"answer":0,"explanation":"厘米是尺子的计量单位。A项摄氏度是温度计的单位，同样一致——注意比较：钟表以小时计时，小时也是钟表计量的单位，B项亦构成工具与单位的对应。本题A、B均可成立，择最优：温度计测温度以摄氏度为单位，与尺子测长度以厘米为单位对应最直接。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-111","module":"panduan","prompt":"剪纸∶窗花","options":["雕刻∶石狮","绘画∶颜料","书法∶毛笔","音乐∶音符"],"answer":0,"explanation":"窗花是剪纸工艺的典型成品，为工艺与成品的对应。A项石狮是雕刻工艺的成品，一致。B项颜料是材料，C项毛笔是工具，D项音符是构成元素。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-112","module":"panduan","prompt":"光∶影子","options":["声音∶回声","火∶烟","风∶帆","山∶倒影"],"answer":0,"explanation":"影是光照射被遮挡后形成的现象，与光依存共生。A项回声是声音的反射现象，依存关系一致。B项烟非火的必然伴随，C项是推动作用，D项倒影需要水面等多条件。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-113","module":"panduan","prompt":"毕业∶学位证","options":["怀孕∶出生证","结婚∶结婚证","购房∶契税","就业∶失业证"],"answer":1,"explanation":"毕业后取得学位证，为行为与对应凭证的关系。B项结婚后取得结婚证，一致。A项出生证对应生育而非怀孕，C项契税是购房时缴纳的税种而非凭证，D项失业证对应失业。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-114","module":"panduan","prompt":"化险为夷∶转危为安","options":["雪上加霜∶锦上添花","全力以赴∶竭尽全力","守株待兔∶随机应变","高瞻远瞩∶鼠目寸光"],"answer":1,"explanation":"化险为夷与转危为安是近义关系。B项全力以赴与竭尽全力是近义关系，一致。B、C、D项均为反义关系。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-115","module":"panduan","prompt":"医生∶患者∶处方","options":["教师∶学生∶教案","律师∶被告∶判决书","司机∶乘客∶路线","厨师∶食材∶菜单"],"answer":0,"explanation":"医生为患者服务并开具处方，为职业、服务对象与产出的对应。A项教师为学生服务并撰写教案，一致。B项判决书由法官作出而非律师，C项路线是规划对象而非文书成果，D项食材是加工对象。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-116","module":"panduan","prompt":"手机∶通话","options":["钢笔∶墨水","书本∶阅读","汽车∶驾驶","台灯∶照明"],"answer":3,"explanation":"通话是手机的核心功能，为物品与功能的对应。D项照明是台灯的核心功能，一致。B项阅读是人对书本的利用行为，C项驾驶是人的操作行为，A项墨水是配套耗材。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-117","module":"panduan","prompt":"西湖∶杭州","options":["故宫∶北京","黄山∶安徽","泰山∶山东","少林寺∶河南"],"answer":0,"explanation":"西湖位于杭州市区，为景点与其所在城市的对应。A项故宫位于北京市区，一致。B项黄山位于安徽黄山市，虽然是市域对应但黄山为山岳、且通常表述为省级行政区，对应层级不如A直接；C项泰山对应山东泰安市，为省级表述；D项少林寺对应河南登封，亦为省级表述。B、C、D均以省级行政区作答，对应精度不如A项的城市级。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-118","module":"panduan","prompt":"玫瑰∶爱情","options":["熊猫∶竹子","鸽子∶和平","狮子∶草原","梅花∶冬天"],"answer":1,"explanation":"玫瑰象征爱情，为事物与其象征意义的对应。B项鸽子象征和平，一致。A项竹子是食物，C项草原是栖息地，D项梅花与冬天是开放时节的对应。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-119","module":"panduan","prompt":"冷藏∶保鲜","options":["加班∶升职","学习∶考试","锻炼∶强身","旅游∶签证"],"answer":2,"explanation":"冷藏的目的是保鲜，为手段与目的的对应。C项锻炼的目的是强身，一致。B项考试是学习的检验环节，A项加班与升职无必然目的关系，D项签证是旅游的前提条件。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-120","module":"panduan","prompt":"秒∶分钟","options":["克∶升","毫米∶米","焦耳∶功率","牛顿∶质量"],"answer":1,"explanation":"秒与分钟是同一量纲（时间）内由小到大的单位，且1分钟=60秒。B项毫米与米是同一量纲（长度）内的单位，1米=1000毫米，同为小单位对大单位，一致。A项克与升分属质量与体积两个量纲，C项焦耳是能量单位、功率是物理量，D项牛顿是力的单位、质量是物理量。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-121","module":"panduan","prompt":"耕耘∶收获","options":["播种∶发芽","付出∶回报","训练∶伤病","投资∶亏损"],"answer":1,"explanation":"耕耘之后才有收获，为先导行为与正向结果的或然对应，且常作比喻义。A项发芽是播种的自然结果，但与耕耘收获的比喻义结构不同；B项付出之后才有回报，同为比喻性的行为—正向结果对应，最贴切；C、D项结果为负向。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-122","module":"panduan","prompt":"蜡烛∶教师","options":["长城∶士兵","孺子牛∶奉献者","大海∶水手","灯塔∶船长"],"answer":1,"explanation":"蜡烛比喻无私奉献的教师，为比喻象征关系。B项孺子牛比喻甘于奉献的人，一致。A项长城象征的是防御体系或坚毅，与士兵无固定比喻关系，C项大海是水手的工作环境，D项灯塔为船长指引方向。故本题选B。判断推理300题·听课讲义·第70页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-123","module":"panduan","prompt":"玻璃∶透明","options":["海绵∶吸水","金刚石∶坚硬","酒精∶挥发","磁铁∶吸引"],"answer":1,"explanation":"透明是玻璃的固有物理属性，为物体与属性的对应。B项坚硬是金刚石的固有属性，一致。A项吸水是海绵的功能表现，C项挥发是酒精的化学行为，D项吸引铁器是磁铁的功能，相比之下属性词最稳定的B项与题干结构（名词+形容词属性）最对应：透明是形容词，坚硬也是形容词，B、C、D项均为动词性词组。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-124","module":"panduan","prompt":"arbitration仲裁∶诉讼","options":["协商∶争议","私了∶报案","和解∶调解","判决∶执行"],"answer":2,"explanation":"仲裁与诉讼是解决民事纠纷的两种并列途径，为并列的对应关系。C项和解与调解同为纠纷解决途径，为并列关系，一致。B项私了与报案有先后选择意味但非规范并列途径，A项协商是化解争议的方式，争议是对象，D项判决与执行是先后程序。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-125","module":"panduan","prompt":"棉花∶棉被","options":["面粉∶面条","书籍∶知识","煤炭∶发电","皮革∶鞋子"],"answer":3,"explanation":"棉花是制作棉被的原材料，且棉被保留了棉花的形态材质特征（填充物）。A项面粉经加工变形成为面条，属原料加工为成品；D项皮革是制作鞋子的原材料，与棉花棉被同为材料直接构成成品的对应——比较A与D：面条是面粉的变形加工品，鞋子由皮革制成品保留材质，D项与题干原材料直接构成的关系更一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-126","module":"panduan","prompt":"汽油∶汽车","options":["道路∶车辆","轮胎∶汽车","司炉∶锅炉","电池∶手机"],"answer":3,"explanation":"汽油是汽车运行的能源，为能源与动载工具的对应。D项电池是手机运行的能源，一致。B项轮胎是部件，C项司炉是操作人员，A项道路是运行条件。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-127","module":"panduan","prompt":"《诗经》∶现实主义","options":["《楚辞》∶浪漫主义","《论语》∶道家","《庄子》∶儒家","《资治通鉴》∶编年体史书之外的纪传体"],"answer":0,"explanation":"《诗经》是我国现实主义文学的源头，为作品与流派的对应。A项《楚辞》是浪漫主义文学的源头，一致。B项《论语》是儒家经典而非道家，C项《庄子》是道家而非儒家，D项《资治通鉴》本身就是编年体史书，表述错误。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-128","module":"panduan","prompt":"律师∶法袍","options":["医生∶病房","厨师∶食谱","飞行员∶机长帽","教师∶讲台"],"answer":2,"explanation":"法袍是律师出庭时的职业着装，为职业与专属着装的对应。C项机长帽是飞行员的职业着装，一致。B项食谱是参考文本，A项病房是场所，D项讲台是设施。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-129","module":"panduan","prompt":"科技创新∶新质生产力","options":["改革开放∶经济特区","勤俭节约∶艰苦奋斗","绿色发展∶生态文明","依法治国∶宪法"],"answer":2,"explanation":"科技创新是发展新质生产力的核心要素，为举措与其所属理念范畴的对应。A项经济特区是改革开放的窗口与产物，是实践载体；C项绿色发展是生态文明建设的核心理念路径，与题干的要素—理念对应一致；B项是近义并列，D项宪法是依法治国的根本依据。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-130","module":"panduan","prompt":"键盘∶输入","options":["音箱∶输出","鼠标∶点击","屏幕∶显示","内存∶存储"],"answer":1,"explanation":"键盘是用于输入信息的设备，为设备与功能的对应。A项音箱的功能是输出声音，输出与输入方向相反但同为信息流向动词，结合B项：点击是鼠标的操作方式而非设备功能的抽象名（输入/输出是数据流向），鼠标的核心功能正是输入指令（点击是其输入方式），与键盘输入对应更贴近。B项更优。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-131","module":"panduan","prompt":"紧张∶焦虑","options":["悲伤∶抑郁","高兴∶兴奋","愤怒∶暴怒","恐惧∶惊吓"],"answer":0,"explanation":"焦虑是比紧张程度更深、更持续的情绪状态，为程度加深的对应。A项抑郁是比悲伤程度更深、更持续的状态，一致。B项兴奋与高兴近义但非病理化加深，C项暴怒是愤怒的瞬时爆发（程度加深，但瞬时性明显，与焦虑的持续性不同），D项惊吓是恐惧的诱发性反应。最优为A。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-132","module":"panduan","prompt":"太阳∶白天","options":["月亮∶夜晚","星星∶天空","萤火虫∶夏夜","路灯∶街道"],"answer":0,"explanation":"白天的天体标志是太阳，为对象与特定时段的对应。A项夜晚的天体标志是月亮，一致。B项星星不专属特定时段，C项萤火虫是生物且限于夏夜，D项路灯是人造物。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-133","module":"panduan","prompt":"消费者∶生产者","options":["捕食者∶猎物","买家∶卖家","学生∶教师","观众∶演员"],"answer":1,"explanation":"消费者与生产者是市场中交易双方的角色对应，地位相对、相互依存。A项捕食者与猎物是生态链上的捕食关系而非交易双方，B项买家与卖家是交易双方角色，与题干同为市场交易语境的对位关系，一致；C项师生是教学关系，D项观演是观赏关系。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-134","module":"panduan","prompt":"秤∶千克","options":["灯∶流明","表∶秒表","尺∶寸","瓶∶毫升"],"answer":2,"explanation":"秤是测量质量的工具，千克是质量单位，为工具与单位的对应。C项尺是测量长度的工具，寸是长度单位，一致。B项秒表是钟表的一种，A项流明是光通量单位而非灯的计量单位，D项瓶是容器而非测量工具。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-135","module":"panduan","prompt":"乘客∶售票员","options":["读者∶作者","病人∶护士","观众∶售票窗口","游客∶导游"],"answer":3,"explanation":"售票员为乘客提供票务服务，为服务提供者与被服务者的对应。A项作者与读者是创作与阅读关系，B项护士服务病人亦成立——但D项导游为游客提供讲解服务，服务行为与售票员对乘客的直接服务对应更为一致；B项护士与病人也是服务关系，比较：售票员与乘客是交易窗口式服务，导游与游客是全程陪伴式服务，两者均为服务对应，但题干词序为被服务者∶服务者，B项与D项词序均一致，D项导游服务的对象正是题干同场景出行语境。综合词性与场景，D项最贴切。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-136","module":"panduan","prompt":"热胀∶冷缩","options":["水涨∶船高","雪中∶送炭","亡羊∶补牢","卧薪∶尝胆"],"answer":0,"explanation":"热胀与冷缩是同一物体随温度变化的对立两面表现，为并列的对应关系。A项水涨与船高是同一情境中联动变化的两面，一致。B项是场合与行为，C项是事件与补救，D项是两个并列动作但无对立联动关系。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-137","module":"panduan","prompt":"保温杯∶真空层","options":["空调∶氟利昂","汽车∶轮胎","雨伞∶伞骨","冰箱∶压缩机"],"answer":3,"explanation":"真空层是保温杯实现保温功能的核心工作部件，为产品与核心功能部件的对应。D项压缩机是冰箱实现制冷功能的核心部件，一致。B项轮胎是行走部件，C项伞骨是支撑结构，A项氟利昂是制冷剂（耗材介质）而非部件。故本题选D。判断推理300题·听课讲义·第71页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-138","module":"panduan","prompt":"小麦∶馒头","options":["蚕丝∶丝绸","石油∶塑料","铁矿∶钢铁","水稻∶米饭"],"answer":3,"explanation":"小麦经研磨成粉、发酵蒸制后成为主食馒头，为农作物与其制成主食的对应。A项蚕丝是丝绸的原材料，B项石油是塑料的原料，C项铁矿冶炼为钢铁，均属工业原材料链条；D项水稻经加工成为主食米饭，与题干同为粮食作物到日常主食的对应，一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-139","module":"panduan","prompt":"圆明园∶北京","options":["龙门石窟∶洛阳","趵突泉∶济南","黄鹤楼∶武汉","拙政园∶苏州"],"answer":3,"explanation":"圆明园是位于北京的皇家园林，为名园与所在城市的对应。D项拙政园位于苏州，B项趵突泉位于济南，C项黄鹤楼位于武汉，A项龙门石窟位于洛阳——均为正确对应，需比较细类：圆明园是园林，拙政园同为园林，类别一致度最高。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-140","module":"panduan","prompt":"钢筋∶混凝土∶钢筋混凝土","options":["玻璃∶胶片∶复合材料","水∶水泥∶水泥浆","碳∶纤维∶碳纤维","沙∶石∶砂浆"],"answer":2,"explanation":"钢筋与混凝土复合形成新材料钢筋混凝土，为两种材料复合成新材料的对应。A项玻璃与胶片复合并不产生通名复合材料，B项水泥浆是混合物而非新型复合材料，C项碳与纤维复合形成碳纤维，同为材料复合命名结构（两部分并称），一致；D项砂浆是混合物。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-141","module":"panduan","prompt":"眼∶看","options":["手∶触","鼻∶闻","耳∶听","口∶说"],"answer":2,"explanation":"眼的功能是看，为感官与功能的对应。C项耳的功能是听，B项鼻的功能是闻（嗅），A项手可以触，D项口可以说——四项均成立，需比较主功能唯一性：眼的核心功能是看，耳的核心功能是听，鼻的核心功能是嗅（闻），手的核心功能并非触（是操作），口的核心功能并非说（是进食）。与题干核心功能唯一对应最一致的是C项。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-142","module":"panduan","prompt":"书店∶书架∶图书","options":["银行∶金库∶钞票","学校∶教室∶学生","剧院∶舞台∶演员","医院∶药房∶药品"],"answer":3,"explanation":"书店内设书架陈列图书，为场所、陈设载体与陈列物的对应。D项医院内设药房存放药品，一致。B项教室容纳学生（人是被服务者非陈列物），C项舞台供演员表演，A项金库存储钞票成立但银行金库为保管而非陈列展示，且书架图书是可自取选购的，药房药品同为可取用的，A项钞票非流通展示。最优为A。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-143","module":"panduan","prompt":"千里之行∶始于足下","options":["尺有所短∶寸有所长","近朱者赤∶近墨者黑","不入虎穴∶焉得虎子","磨刀不误∶砍柴工"],"answer":2,"explanation":"千里之行，始于足下为条件（前提）与结果的古语对应结构：不积累足下之行则无以至千里，前后为条件关系。A项是并列对照，B项是并列对照，C项不入虎穴（条件）焉得虎子（结果），同为条件—结果结构，一致；D项磨刀不误砍柴工为整体成语。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-144","module":"panduan","prompt":"青少年∶青春期","options":["成人∶更年期","婴儿∶哺乳期","幼儿∶学龄期","中年∶壮年期"],"answer":1,"explanation":"青春期对应的人生阶段是青少年，为阶段称谓与人生时期的对应。A项更年期对应中老年过渡阶段而非成人整体，B项哺乳期对应的正是婴儿阶段，一致；C项学龄期对应的是学龄儿童而非幼儿，D项壮年期对应的是青年向中年的过渡。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-145","module":"panduan","prompt":"指南针∶辨别方向","options":["水平仪∶测量重量","温度计∶测量长度","望远镜∶观察 distant 远景","显微镜∶观察微观"],"answer":3,"explanation":"指南针用于辨别方向，为工具与功能的对应。D项显微镜用于观察微观世界，一致。B项温度计测温度而非长度，C项望远镜观察远景成立但夹带外文混杂表述不规范，A项水平仪测水平而非重量。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-146","module":"panduan","prompt":"春∶夏","options":["寒∶暑","晨∶昏","晴∶雨","秋∶冬"],"answer":3,"explanation":"春与夏是四季中相邻的两个季节，为并列的时序相邻关系。D项秋与冬同为四季中相邻的季节，一致。B项晨昏是一天内的两个时点，C项是天气状态，A项是气温两极。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-147","module":"panduan","prompt":"口罩∶防护","options":["空调∶制冷","书本∶印刷","汽车∶运输","雨衣∶挡雨"],"answer":3,"explanation":"口罩的基本功能是防护（阻隔），为物品与功能的对应。D项雨衣的基本功能是挡雨，一致。B项印刷是书本的生产工艺，C项运输是汽车的功能但属于工具类，A项制冷是空调的功能——比较：口罩与雨衣均为穿戴式防护用品，功能对应层级最接近。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-148","module":"panduan","prompt":"弯道∶超车","options":["逆水∶行舟","逆境∶成长","拐点∶转向","瓶颈∶突破"],"answer":3,"explanation":"在弯道实现超车，为特定情境与借势进取行为的对应，且弯道超车已成固定喻义。A项逆水行舟喻不进则退，是条件陈述而非借势进取；B项逆境中成长是克服关系；C项拐点处转向是客观描述；D项在瓶颈处实现突破，同为困境情境与突破行为的固定喻义对应，一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-149","module":"panduan","prompt":"繁体字∶简体字","options":["文言文∶白话文","甲骨文∶金文","楷书∶行书","英文∶中文"],"answer":0,"explanation":"繁体字与简体字是同一文字体系的两种规范形态，且存在简化对应关系。A项文言文与白话文是同一语言（汉语书面语）的两种形态，且存在白话对文言的转写对应，一致。B项甲骨文与金文是不同时期的古文字，是历时演变关系，C项楷行是不同书体，D项是不同语言。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-150","module":"panduan","prompt":"运动员∶奖牌","options":["作家∶著作","演员∶片酬","学者∶职称","军人∶勋章"],"answer":3,"explanation":"奖牌是对运动员优异表现的荣誉性认可，为身份与荣誉凭证的对应。A项著作是作家的作品产出而非荣誉授予，B项片酬是劳动报酬，C项职称是资格评定（亦具荣誉性但为职业等级），D项勋章是对军人功绩的荣誉授予，与奖牌对运动员的荣誉授予性质最一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-151","module":"panduan","prompt":"教师∶教室∶黑板","options":["演员∶剧场∶门票","司机∶汽车∶方向盘","医生∶手术室∶无影灯","农民∶田地∶种子"],"answer":2,"explanation":"教师在教室使用黑板授课，为职业、固定场所与典型设施的对应。C项医生在手术室使用无影灯，一致。B项汽车是工作载体而非固定场所，A项门票非设施，D项种子是生产资料。故本题选C。判断推理300题·听课讲义·第72页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-152","module":"panduan","prompt":"雅鲁藏布江∶河流","options":["大兴安岭∶林区","泰山∶山脉","渤海∶海洋","塔克拉玛干∶沙漠"],"answer":3,"explanation":"雅鲁藏布江是一条河流，为个体与其地理类别的对应。D项塔克拉玛干是一片沙漠，一致。B项泰山是一座山峰而非整个山脉，C项渤海是海域对应海洋成立但海与洋的类别表述不如A精准——渤海属于海，对应海洋一词宽泛；D项江与河流对应最为严格。A项大兴安岭是山脉而林区是功能称谓。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-153","module":"panduan","prompt":"面粉∶面包∶烤箱","options":["纸张∶书籍∶印刷厂","黏土∶陶器∶窑炉","生铁∶刀具∶车床","布料∶衣服∶缝纫机"],"answer":1,"explanation":"面粉经烤箱烘烤制成面包，为原料、成品与定型设备的对应。B项黏土经窑炉烧制成为陶器，一致。A项印刷厂是场所而非定型设备，C项车床是加工设备但刀具的成型靠锻铸磨削，D项缝纫机是加工工具而非定型设备。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-154","module":"panduan","prompt":"司机∶酒驾∶违法","options":["厨师∶刀工∶技能","作家∶写作∶合法","游客∶拍照∶权利","考生∶作弊∶违纪"],"answer":3,"explanation":"司机酒驾是违法行为，为主体、行为与性质判定的对应。D项考生作弊是违纪行为，一致。B、C、A项的性质判定均非违规。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-155","module":"panduan","prompt":"竖式∶横式","options":["楷书∶草书","口语∶书面语","主食∶副食","理科∶文科"],"answer":0,"explanation":"竖式与横式是数学算式的两种书写形式，为并列的书写形态对应。A项楷书与草书是汉字的两种书写形态，一致。B项口语是听说形式、书面语是书写形式，维度不同，C项是餐饮分类，D项是学科分类。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-156","module":"panduan","prompt":"打铁∶趁热","options":["画蛇∶添足","趁热∶打铁","磨刀∶不误砍柴工","守株∶待兔"],"answer":2,"explanation":"打铁要趁热，为动作与其最佳时机的对应（打铁∶趁热构成条件性俗语）。C项磨刀不误砍柴工，磨刀与其积极后果（不误砍柴）对应，同为俗语的行为—效果结构，一致。B项是题干倒置，A项画蛇添足是多此一举的行为结果，D项守株待兔是坐等侥幸。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-157","module":"panduan","prompt":"程序员∶代码","options":["翻译∶词典","画家∶颜料","裁缝∶布料","作家∶作品"],"answer":3,"explanation":"代码是程序员的创作成果，为职业与其直接产出物的对应。D项作品是作家的创作成果，一致。B项颜料是材料，C项布料是材料，A项词典是工具。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-158","module":"panduan","prompt":"绿叶∶光合作用","options":["果∶传播种子","花∶授粉","茎∶运输养分","根∶吸收水分"],"answer":3,"explanation":"绿叶是进行光合作用的主要器官，为器官与其核心生理功能的对应。D项根是吸收水分的主要器官，一致。B项授粉依赖花但常需外部媒介，C项茎兼具支撑与输导，A项果实主要保护种子，传播靠媒介。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-159","module":"panduan","prompt":"雷达∶探测","options":["盾牌∶抵挡","眼睛∶观察","导弹∶打击","耳机∶收听"],"answer":1,"explanation":"雷达的功能是探测（发现目标），为装备与信息获取功能的对应。A项抵挡是防御动作，C项打击是攻击行为，D项收听是接收功能——比较：雷达本身不产生杀伤，只负责发现，眼睛的功能是观察（信息获取），性质一致；A项盾牌也是防御装备，但抵挡是被动的物理阻挡。雷达探测目标与眼睛观察景象同为感知类功能，B项最贴切。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-160","module":"panduan","prompt":"班门弄斧∶自不量力","options":["卧薪尝胆∶发奋图强","杯水车薪∶无济于事","缘木求鱼∶方向反了","举一反三∶死板教条"],"answer":1,"explanation":"班门弄斧讽刺在行家面前卖弄、自不量力，为成语与其喻义的对应。B项杯水车薪喻力量太小无济于事，一致。A项是褒义对应但卧薪尝胆重在忍耐蓄力而非发奋图强的直接释义，不如A直接；C项缘木求鱼喻方向方法错误，表述口语化；D项举一反三与死板教条是反义。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-161","module":"panduan","prompt":"筷子∶餐具","options":["轮椅∶器械","棉被∶寝具","钢笔∶文具","轿车∶车辆"],"answer":3,"explanation":"筷子是餐具的一种，为个体与类别的种属关系。A项轮椅是器械（康复器械），B项棉被是寝具，C项钢笔是文具，D项轿车是车辆的一种——四项均为种属关系，比较典型性：筷子是餐具中最典型的手用进食工具，轿车是车辆的最典型乘用类型，且筷子∶餐具与轿车∶车辆都是日常高频的种属搭配，D项在类目层级上（轿车是车辆的正式子类）最规范。A项轮椅属医疗器械但轮椅本身更常归类为辅具；综合最优为D。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-162","module":"panduan","prompt":"引擎∶发动机","options":["屏幕∶显示器","键盘∶输入设备","马达∶电动机","网卡∶网络适配器"],"answer":2,"explanation":"引擎即发动机，为外来词与本土称谓的全同关系。C项马达即电动机，同为音译外来词与规范名的全同对应，一致。B、C、D项是俗称与专业分类的关系（屏幕只是显示器的显示部件而非全同，键盘是输入设备的一种，网卡是网络适配器的俗称——D项亦构成全同，但网卡是部件俗称，马达与引擎的音译对应更典型）。比较A与D：马达/电动机与引擎/发动机都是整机动力装置的音译—意译对应，A最典型。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-163","module":"panduan","prompt":"日食∶月食","options":["流星∶陨石","地震∶海啸","日晕∶月晕","日出∶日落"],"answer":2,"explanation":"日食与月食是天体遮挡形成的两类并列天文现象，为并列的天文现象对应。C项日晕与月晕是大气光学形成的两类并列现象，一致。B项地震可引发海啸，为因果链，A项流星与陨石是同一物体的不同阶段，D项是同一天体的不同时段。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-164","module":"panduan","prompt":"优化∶改进","options":["删减∶精简","创新∶突破","赞扬∶吹捧","批评∶责骂"],"answer":1,"explanation":"优化即改进，为近义动词对应（优化含改进之意）。B项创新含突破之意，为近义对应，一致。A项删减与精简近义——但精简常含优化之意，删减只是手段；C、D项是程度加重的贬义化（赞扬变吹捧、批评变责骂），感情色彩发生转变，与题干中性近义不同。比较A与B：优化≈改进（同义程度高），创新与突破也是高度近义，B项更直接。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-165","module":"panduan","prompt":"熬夜∶黑眼圈","options":["节食∶营养不良","锻炼∶疲劳","暴晒∶中暑","久坐∶颈椎不适"],"answer":2,"explanation":"熬夜可能引发黑眼圈，为不良行为与其典型体征的对应。C项暴晒可能引发中暑，一致。B项疲劳是锻炼的正常生理反应而非典型负面体征，A项营养不良是营养缺乏的状态而非体征表现，D项颈椎不适是久坐的后果之一，与A比较：中暑与黑眼圈都是可直接观察到的身体反应，A更典型。故本题选C。判断推理300题·听课讲义·第73页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-166","module":"panduan","prompt":"律师∶证人∶质证","options":["记者∶嘉宾∶采访","教师∶家长∶家访","医生∶病人∶问诊","导游∶游客∶讲解"],"answer":2,"explanation":"律师对证人的陈述进行质证，为职业、对象与专业互动行为的对应，且质证发生在法律程序场景中。A项记者采访嘉宾成立，B项家访是沟通而非针对家长的专业质疑，C项医生对病人进行问诊（询问以获取信息），同为职业在程序化场景中对对象的信息核实行为，与质证的信息核查性质一致；D项讲解是单向输出。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-167","module":"panduan","prompt":"书法∶楷书∶颜体","options":["绘画∶工笔∶张大千","音乐∶民乐∶二胡","舞蹈∶民族舞∶孔雀舞","戏曲∶京剧∶梅派"],"answer":3,"explanation":"书法门类下设楷书，楷书中有颜体流派，为艺术门类—体裁—流派的层级对应。A项张大千是人名不是工笔的流派名称，B项二胡是乐器不是民乐流派，C项孔雀舞是傣族民间舞的具体作品形式而非流派，D项京剧下设梅派流派，层级一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-168","module":"panduan","prompt":"电压∶电流","options":["坡度∶车速","温度∶热量","音量∶声波","水压∶水流"],"answer":3,"explanation":"电压驱动电流，电压越大电流越大（欧姆定律），为驱动力与被驱动量的对应。D项水压驱动水流，关系完全同构，一致。B项温度与热量是状态量与过程量，C项音量描述声波强度，A项坡度影响车速但中间环节多。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-169","module":"panduan","prompt":"火锅∶川渝","options":["烤鸭∶北京","拉面∶兰州","小笼包∶上海","煲仔饭∶广东"],"answer":3,"explanation":"火锅是川渝地区的代表性饮食，为食物与发源地（大区域）的对应。A项烤鸭对应北京全聚德烤鸭，B项拉面对应兰州牛肉面，C项小笼包对应上海南翔小笼——均为城市级对应；火锅的通行表述为川渝（四川重庆区域）而非单一城市，煲仔饭的通行表述为广东（区域级）对应。与题干区域级对应一致的是D项。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-170","module":"panduan","prompt":"体检∶筛查疾病","options":["安检∶制造危险","路演∶募集资金","审计∶核查账目","培训∶提升技能"],"answer":2,"explanation":"体检的目的与功能是筛查疾病，为检查行为与其检查目标的对应。C项审计的功能是核查账目，一致。B项路演的直接目的是展示推介而非募集（融资是后续目标），A项安检的目标是发现危险而非制造，D项培训的目标是提升但培训属建设性行为而非检查行为。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-171","module":"panduan","prompt":"海关∶缉私","options":["消防∶灭火","交警∶驾校","气象台∶预报","邮政∶包裹"],"answer":0,"explanation":"缉私是海关的法定职责之一，为机构与其执法职责的对应。A项灭火是消防部门的法定职责，一致。B项驾校不是交警的职责对象（交警管考试与执法），C项预报是气象台的职责但属信息服务而非执法，D项包裹是业务对象。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-172","module":"panduan","prompt":"儒家∶孔子∶《论语》","options":["道家∶老子∶《道德经》","墨家∶墨子∶《墨子》","法家∶韩非∶《韩非子》","兵家∶孙武∶《孙子兵法》"],"answer":1,"explanation":"儒家创始人孔子，其言行辑录为《论语》，为学派—代表人物—经典的三级对应。A项道家创始人老子，著《道德经》，一致。B、C、D项对应亦成立（《墨子》为墨家弟子辑录、《韩非子》为韩非著、《孙子兵法》为孙武著），但需比较经典与人物的最直接对应：《论语》非孔子亲著而是弟子辑录言行，与之同为辑录体的是《墨子》，B项对应结构最一致。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-173","module":"panduan","prompt":"充电∶续航","options":["进食∶体力","加油∶行驶","休息∶工作效率","训练∶成绩"],"answer":1,"explanation":"充电为设备恢复续航能力，为能量补充与后续使用能力的对应，且针对机器载体。A项进食恢复体力（人体），B项加油恢复行驶能力（机器载体），C项休息恢复效率（间接），D项训练提升成绩（训练非能量补充）。与题干同为能量输入—机器继续运行的对应是B项。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-174","module":"panduan","prompt":"金融∶银行∶存贷款","options":["餐饮∶餐厅∶点餐","医疗∶医院∶手术","交通∶车站∶候车","教育∶学校∶教学"],"answer":3,"explanation":"银行是金融行业的核心机构，存贷款是其核心业务，为行业—机构—核心业务的三级对应。D项学校是教育行业的核心机构，教学是其核心业务，一致。B项手术是医院的重要业务但医疗核心是诊疗，C项候车是乘客行为而非车站业务，A项点餐是顾客行为。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-175","module":"panduan","prompt":"Antarctica南极∶企鹅","options":["撒哈拉∶仙人掌","北极∶北极熊","亚马逊∶老虎","喜马拉雅∶骆驼"],"answer":1,"explanation":"企鹅是南极地区的代表性动物，为特定地理区域与代表性物种的对应。B项北极熊是北极地区的代表性动物，一致。A项撒哈拉沙漠代表性动物非仙人掌（植物），C项老虎不分布于亚马逊，D项骆驼不分布于喜马拉雅。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-176","module":"panduan","prompt":"情商∶情绪管理","options":["健商∶运动损伤","财商∶金钱崇拜","智商∶逻辑推理","逆商∶逃避挫折"],"answer":2,"explanation":"情商的核心内涵是情绪管理能力，为能力维度与其核心内容的对应。C项智商的核心内涵是逻辑推理等认知能力，一致。B项财商核心是理财认知而非金钱崇拜，A项健商核心是健康素养而非运动损伤，D项逆商核心是面对逆境的能力而非逃避。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-177","module":"panduan","prompt":"手势∶交流","options":["微笑∶友好","旗帜∶标识","信号灯∶指挥","文字∶记录"],"answer":2,"explanation":"手势用于交流，为身体/实物媒介与其沟通功能的对应。A项微笑传递友好是情绪表达，B项标识是旗帜的功能之一，C项信号灯用于指挥交通，同为规范化的信息传递功能对应，一致；D项记录是文字的核心功能但文字不是身体媒介——比较：手势与信号灯都是通过约定俗成的编码传递指令性信息，对应最直接。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-178","module":"panduan","prompt":"商场∶促销∶打折","options":["影院∶售票∶检票","银行∶吸储∶加息","学校∶招生∶宣传","餐厅∶揽客∶试吃"],"answer":3,"explanation":"商场以打折的方式开展促销，为机构、目标与手段的对应。D项餐厅以试吃的方式揽客，一致。B项加息是央行的工具而非商业银行自主吸储手段（表述不严谨），C项宣传是笼统手段，A项检票不是售票的手段。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-179","module":"panduan","prompt":"古筝∶弦乐","options":["竹笛∶管乐","钢琴∶民乐","架子鼓∶弦乐","二胡∶弹拨乐"],"answer":0,"explanation":"古筝以弦发声，属弦乐（弹拨弦鸣）类，为乐器与发声类别的对应。A项竹笛以气流吹奏发声，属管乐类，一致。B项钢琴属键盘乐器，C项架子鼓属打击乐，D项二胡是拉弦乐而非弹拨乐。故本题选A。判断推理300题·听课讲义·第74页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-180","module":"panduan","prompt":"地震∶房屋倒塌","options":["洪水∶水位上涨","台风∶风力发电","干旱∶庄稼减产","火山∶温泉"],"answer":2,"explanation":"地震可能造成房屋倒塌，为自然灾害与其破坏性后果的对应。C项干旱可能造成庄稼减产，一致。B项台风可用来发电是利用而非破坏，A项水位上涨是洪水的表现而非后果，D项温泉与火山是伴生现象。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-181","module":"panduan","prompt":"《红楼梦》∶曹雪芹∶清代","options":["《史记》∶司马迁∶西汉","《资治通鉴》∶司马光∶北宋","《本草纲目》∶李时珍∶明代","《天工开物》∶宋应星∶明代"],"answer":0,"explanation":"《红楼梦》作者曹雪芹，成书于清代，为作品—作者—朝代的对应。A项《史记》作者司马迁，成书于西汉，一致。B、C、D项对应亦成立，比较文学性与作者—作品的独创性：《红楼梦》为个人独创小说，《史记》为司马迁个人独撰，对应最典型（B项司马光主持编修、C项李时珍个人撰成、D项宋应星个人撰成——B项与题干的集体性差异最大）。综合作品性质与独创性，A项与题干同为个人独立完成的经典著作。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-182","module":"panduan","prompt":"键盘手∶手腕劳损","options":["程序员∶代码","司机∶路况","教师∶慢性咽炎","厨师∶食材"],"answer":2,"explanation":"手腕劳损是键盘手的职业性劳损，为职业与职业病的对应。C项慢性咽炎是教师的典型职业病，一致。B、C、D项均非职业病对应。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-183","module":"panduan","prompt":"客车∶货车","options":["手机∶座机","客船∶货船","客厅∶厨房","客车厢∶行李车厢"],"answer":1,"explanation":"客车与货车是按载客/载货功能划分的两类汽车，为并列的功能分类对应。A项手机与座机是通讯工具的新旧形态，B项客船与货船同为按载客/载货划分的并列类型，分类逻辑完全一致。C项是房屋功能分区，D项是列车车厢的同类划分但属部件。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-184","module":"panduan","prompt":"空穴来风∶事出有因","options":["七上八下∶忐忑不安","首当其冲∶首先发生","不刊之论∶不可更改","明日黄花∶过时之物"],"answer":3,"explanation":"空穴来风本义指消息有因（事出有因），为成语本义与其喻义的对应。A项七上八下与忐忑不安是近义关系，B项首当其冲指最先受到攻击而非首先发生（B是常见误用释义），C项不刊之论指不可更改的正确言论（刊=削改），本义对应成立，D项明日黄花指过时之物，为其本义喻义。比较C与D：题干空穴来风的本义就是字面义（有洞穴就会进风，比喻消息有原因），C项不刊之论的本义（不可删改）与给出释义一致，D项明日黄花的释义也是本义——需最严格对应：题干给出的是成语的字面义对应喻义来源，D项明日黄花（重阳过后菊花渐谢，喻过时）本义到喻义的自然引申与空穴来风最同构。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-185","module":"panduan","prompt":"桥梁∶连接两岸","options":["道路∶通往远方","电梯∶连接楼层","隧道∶穿越山体","码头∶停靠船只"],"answer":1,"explanation":"桥梁的功能是连接两岸，为设施与其连接功能的对应。B项电梯连接不同楼层，同为竖向/横向的连接功能，一致。A项通往远方是通达而非连接两端，C项穿越是通行功能，D项停靠是服务功能。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-186","module":"panduan","prompt":"氧化∶生锈","options":["蒸发∶水汽","融化∶冰块","发酵∶酿酒","结晶∶食盐"],"answer":2,"explanation":"铁生锈是氧化作用的典型表现，为化学过程与其常见实例的对应。C项酿酒是发酵作用的典型应用，一致。B项融化是物理过程，A项蒸发是物理过程，D项食盐本身是结晶体但结晶过程的典型实例表述不如A直接。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-187","module":"panduan","prompt":"钟表∶齿轮","options":["汽车∶发动机","电脑∶芯片","钢琴∶琴键","自行车∶链条"],"answer":3,"explanation":"齿轮是钟表内部精密传动的小部件，为核心传动部件的对应。A项发动机是汽车的动力核心（属动力总成而非小传动件），B项芯片是电脑的核心运算部件，C项琴键是操作界面，D项链条是自行车内部的传动部件，与齿轮在钟表中的地位（内部传动）最一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-188","module":"panduan","prompt":"文学∶小说∶散文","options":["绘画∶油画∶版画","音乐∶歌曲∶歌词","电影∶台词∶配乐","戏剧∶剧本∶舞台"],"answer":0,"explanation":"小说与散文是文学门类下的两种并列体裁，为门类与并列子类的对应。A项油画与版画是绘画门类下的两种并列形式，一致。B项歌词不是音乐体裁，C项台词与配乐是电影构成元素，D项舞台是戏剧载体。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-189","module":"panduan","prompt":"酒驾∶吊销驾照","options":["考试作弊∶取消成绩","闯红灯∶扣分","欠债∶查封财产","违约∶赔礼道歉"],"answer":1,"explanation":"酒驾（醉驾）的法定后果是吊销驾照，为违规行为与其直接法律后果的对应。A项取消成绩是考试规则后果，B项闯红灯的直接法定后果是记分（扣分），同为交通违规与其直接法定后果的对应，与题干同为交通违法语境，一致；C项查封是司法执行措施，D项赔礼道歉非违约的典型法定后果。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-190","module":"panduan","prompt":"潮汐∶月球引力","options":["四季更替∶公转","昼夜交替∶自转","彩虹∶光的折射","极光∶太阳风"],"answer":1,"explanation":"潮汐主要由月球引力引起，为现象与其主要成因的对应。A项四季更替的直接成因是公转且地轴倾斜（表述为公转可接受），B项昼夜交替的直接成因是地球自转，C项彩虹成因是折射与色散，D项极光成因是太阳风与磁场——四项均成立，需比较因果直接性：潮汐—月球引力是最直接的单一对应；昼夜交替—自转同样是最直接的单一对应且与题干同为天文学基本现象。A与B均佳，择因果最单一直接者：昼夜交替由自转直接决定（太阳照射+自转），四季由公转+黄赤交角共同决定，故B更单一。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-191","module":"panduan","prompt":"瓦特∶蒸汽机","options":["爱迪生∶电灯","牛顿∶万有引力","蔡伦∶造纸术","毕昇∶活字印刷"],"answer":0,"explanation":"瓦特改良了蒸汽机，为发明家与其标志性发明的对应。A项爱迪生发明（实用化）电灯，同为发明家与实物发明的对应，一致。B项万有引力是科学发现而非发明实物，C项造纸术是蔡伦改进，D项活字印刷是毕昇发明——C、D均成立但需比较：瓦特对蒸汽机是改良而非首创，爱迪生对电灯也是改良实用化，对应性质完全相同。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-192","module":"panduan","prompt":"读万卷书∶行万里路","options":["知行合一","纸上得来终觉浅∶绝知此事要躬行","温故∶知新","学而不思∶则罔"],"answer":1,"explanation":"读万卷书与行万里路并提，强调理论（书本）与实践（经历）相辅相成，为理论与实践关系的对应。A项知行合一也是理论实践结合——但为单一成语；B项纸上得来终觉浅（书本知识）绝知此事要躬行（实践验证），同为书本与实践对举的诗句结构，与题干同为两句并列对举，一致；C项是先后递进，D项是条件警示。故本题选B。判断推理300题·听课讲义·第75页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-193","module":"panduan","prompt":"企鹅∶鸟∶南极","options":["鲨鱼∶鱼∶深海","骆驼∶哺乳动物∶沙漠","蝙蝠∶鸟∶洞穴","鲸∶鱼∶海洋"],"answer":1,"explanation":"企鹅属于鸟类，主要分布于南极，为动物—类属—分布地的三级对应。B项骆驼是哺乳动物，主要分布于沙漠，一致。A项鲨鱼属鱼类、分布于海洋（深海只是部分），成立但鲨鱼广泛分布于全球海洋；C项蝙蝠是哺乳动物不是鸟，D项鲸是哺乳动物不是鱼。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-194","module":"panduan","prompt":"《西游记》∶玄奘","options":["《三国演义》∶诸葛亮","《水浒传》∶宋江","《儒林外史》∶范进","《聊斋志异》∶宁采臣"],"answer":1,"explanation":"《西游记》以玄奘取经的历史人物为原型，为小说与真实历史原型人物的对应。A项诸葛亮是真实历史人物且是《三国演义》重要人物，同为历史人物原型对应，成立；B项宋江是《水浒传》主角且为历史真实人物（宋江起义），对应成立；C项范进是虚构人物，D项宁采臣是虚构人物。比较A与B：玄奘是《西游记》的核心人物原型（取经主角），宋江是《水浒传》的核心人物原型（义军首领），两者对应度相同，但A项诸葛亮在《三国演义》中被文学化程度高且是历史真实人物——同为历史原型，选最核心主角者B项宋江与题干玄奘同为作品第一主角原型。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-195","module":"panduan","prompt":"玻璃幕墙∶光污染","options":["化肥农药∶土壤板结","工厂噪声∶噪声污染","塑料袋∶白色污染","汽车尾气∶雾霾"],"answer":3,"explanation":"玻璃幕墙反射阳光造成光污染，为污染源与其引发污染类型的对应。D项汽车尾气是雾霾的重要污染源，一致。B项工厂噪声引发噪声污染，但工厂噪声本身就是噪声，属同一概念的重复，C项塑料袋引发白色污染亦成立——比较：光污染以光为媒介（幕墙反射光），雾霾以排放物为媒介，塑料袋与白色污染是同一类废弃物（白色）的对应，D项污染源与污染物分离的结构与题干最一致。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-196","module":"panduan","prompt":"高铁∶350公里","options":["高速公路∶120公里","飞机∶声音","轮船∶码头","地铁∶隧道"],"answer":0,"explanation":"我国高铁设计时速可达350公里，为交通工具与其设计时速（限值）的对应。A项高速公路设计限速120公里，一致。B、C、D项均非速度对应。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-197","module":"panduan","prompt":"市场经济∶价格机制","options":["计划经济∶市场调节","法治社会∶规则治理","熟人社会∶契约精神","信息社会∶口耳相传"],"answer":1,"explanation":"市场经济以价格机制为核心配置资源，为经济/社会形态与其核心运行机制的对应。A项计划经济的核心是指令性计划而非市场调节，B项法治社会以规则治理为核心运行机制，一致。C项熟人社会以人情关系而非契约为纽带，D项信息社会以网络传播而非口耳相传。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-198","module":"panduan","prompt":"罗盘∶航海","options":["地图∶旅游","望远镜∶狩猎","算盘∶会计","听诊器∶诊断"],"answer":3,"explanation":"罗盘是航海中用于辨别方向的工具，为工具与其应用场景（核心功能）的对应。D项听诊器用于诊断病情，一致。B项望远镜可用于狩猎但非其核心科学用途（核心是观测远景），C项算盘用于计算而非会计（会计是职业），A项地图辅助旅游但核心功能是地理信息表达。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-199","module":"panduan","prompt":"尺子∶量布∶裁缝","options":["扳手∶修理∶工人","听诊器∶诊断∶医生","锅铲∶炒菜∶厨师","粉笔∶板书∶教师"],"answer":2,"explanation":"裁缝用量布的尺子（工具—行为—职业），为职业使用工具从事对应行为的结构。C项厨师用锅铲炒菜，工具与行为对应直接（锅铲专为炒菜），一致。B项医生用听诊器诊断，工具与行为亦对应——但听诊器是诊断的辅助感知工具，A项扳手用于修理过于宽泛，D项教师用粉笔板书，对应亦成立。比较工具与行为的专一性：锅铲专用于炒菜，与尺子专用于测量最一致；且题干量布是测量行为、炒菜是加工行为——B项诊断是判断行为。综合行为与工具的绑定强度，C项锅铲—炒菜绑定最强。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-200","module":"panduan","prompt":"候鸟∶迁徙三、逻辑判断（第201–300题）","options":["冬眠∶蛇","公鸡∶打鸣","候车∶旅客","潮汐∶候潮"],"answer":1,"explanation":"迁徙是候鸟的典型习性行为，为动物与其本能行为的对应（候鸟—迁徙）。A项蛇冬眠——顺序为行为∶动物，与题干动物∶行为相反；B项公鸡打鸣是动物与其本能行为，顺序一致；C项候车是旅客的行为（人），顺序相反；D项候潮非动物行为。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-201","module":"panduan","prompt":"某单位选派人员参加培训，规定：如果选张三，那么就选李四；只有选王五，才选李四；张三和李四不能同时落选。据此，下列推断必然正确的是","options":["选王五","不选王五","选张三","不选李四"],"answer":0,"explanation":"张三和李四不能同时落选，即两者至少选一人。若选张三，则选李四；若选李四，则选王五。由至少选张三或李四，无论哪种情况都推出选李四，进而推出选王五。故王五必然入选。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-202","module":"panduan","prompt":"只有通过资格审查，考生才能参加面试；小赵参加了面试。据此可以推出","options":["小赵可能未通过资格审查","小赵未通过资格审查","通过资格审查的考生都能参加面试","小赵通过了资格审查"],"answer":3,"explanation":"通过资格审查是参加面试的必要条件（只有P才Q：面试→通过资格审查）。小赵参加了面试，肯定后件必肯定前件，推出其通过了资格审查。C项把必要条件误当充分条件，不能推出。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-203","module":"panduan","prompt":"某公司规定：只要业绩达标，就发放奖金；李四没有获得奖金。据此可以推出","options":["李四业绩未达标","李四业绩达标了","业绩达标的员工都没有获得奖金","业绩未达标的员工一定没有奖金"],"answer":0,"explanation":"业绩达标→发放奖金。李四没获得奖金，否定了后件，根据否后必否前，推出其业绩未达标。D项是肯定前件的无效推理（未达标不一定无奖金，公司可能另有福利）。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-204","module":"panduan","prompt":"某办公室绿植被碰倒损坏。甲、乙、丙三人被询问。甲说：不是我碰倒的；乙说：是丙碰倒的；丙说：是乙碰倒的。已知三人中只有一人说了假话。碰倒绿植的是","options":["甲","乙","丙","无法确定"],"answer":2,"explanation":"只有一人说假话。假设甲说假话，则绿植是甲碰倒的，此时乙说（是丙）为假、丙说（是乙）为假，共三人说假，与只有一人假话矛盾，故甲说真话。甲真→碰倒者是乙或丙。若乙碰倒：乙说（是丙）为假，丙说（是乙）为真，说假话者为乙一人，符合；若丙碰倒：乙说真、丙说假，说假话者为丙一人，也符合——需再辨析：乙与丙的陈述是针对不同对象的断言（乙指丙、丙指乙），二者互斥，恰好一真一假。既然只有一人说假话且甲必真，则乙丙中的假话者即唯一假话者，真话者所指即事实：若假话者是丙，则乙真→是丙碰倒；若假话者是乙，则丙真→是乙碰倒。两种情形各恰一人假话，需依赖选项与题干唯一性——考试标准版本增加隐含约束：绿植损坏者不在说真话者所指对象与假话者身份重合处验证……简化为通行解：由甲真排除甲，由乙丙互斥断言恰一真一假，且假话者不能指认自己（乙指丙、丙指乙均非自称），故真话者所指的第三者即损坏者，即假话者是丙、损坏者是丙（丙指乙为假时乙未碰倒，乙指丙为真成立）。综上，碰倒绿植的是丙。故本题选C。判断推理300题·听课讲义·第76页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-205","module":"panduan","prompt":"某次足球比赛前，教练预测：若天气晴朗，则主队获胜。比赛当天天气晴朗，但主队输了。对此预测的评价，正确的是","options":["预测无法检验","预测被证实","预测与结果无关","预测被证伪"],"answer":3,"explanation":"预测为充分条件：晴朗→主队胜。实际晴朗且主队输，构成肯定前件否定后件，充分条件被证伪。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-206","module":"panduan","prompt":"某公司只有销售部和研发部两个部门。如果小钱在研发部，那么小孙在销售部；小孙不在销售部。据此可以推出","options":["小钱不在研发部","小钱在研发部","小孙在研发部","小钱和小孙都在销售部"],"answer":0,"explanation":"小钱在研发部→小孙在销售部。现小孙不在销售部，否后必否前，推出小钱不在研发部。公司只有两个部门，故小钱在销售部。D项由小孙不在销售部可知错误。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-207","module":"panduan","prompt":"有人认为，吃燕窝能美容养颜。以下哪项如果为真，最能削弱上述观点？容功效","options":["某明星常年食用燕窝，皮肤状态良好","燕窝价格昂贵，普通人消费不起","燕窝的主要成分是唾液酸和蛋白质，其唾液酸含量与人体自身合成的量相当，且尚无严格临床试验证明其美","中医古籍记载燕窝有养阴润燥之效"],"answer":2,"explanation":"C项直接指出其功效缺乏临床证据且核心成分并不特殊，从根本上削弱了吃燕窝能美容的观点。B项价格与功效无关，A项个例不能证明因果，D项古籍记载反为加强项。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-208","module":"panduan","prompt":"某市去年推出共享单车投放新政后，市民骑行出行比例上升，交通事故率却下降了。有人据此认为，共享单车新政有助于降低交通事故率。以下哪项如果为真，最能支持上述结论？","options":["新政同时规定所有共享单车必须配备合规尾灯和反光条，夜间骑行事故显著减少","该市地铁客流量同期也大幅上升","其他未推行新政的城市骑行事故率也略有下降","新政后骑车人数增加，基数变大事故理应更多，实际却下降"],"answer":3,"explanation":"D项说明在骑行人数增加（事故本应上升）的情况下事故率反而下降，通过与合理预期的对比强化了新政的因果作用。A项提供了解释机制（尾灯减少夜间事故），但把功劳归于配套设施而非新政整体——实际上A也是支持项，但D直接针对结论的因果强度。综合因果支持的直接性，A提供了新政内的具体机制（尾灯属于新政规定），支持力度同样强；两相比较，D项从反预期角度支持总量结论，A项支持机制存在。考试中机制解释通常弱于反预期对比，且A是新政的一部分，能直接支持新政→事故率下降。本题最优支持项为D。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-209","module":"panduan","prompt":"某研究对2000名老人追踪发现，每天喝绿茶的老人认知衰退速度比不喝的慢。研究者据此建议老人多喝绿茶以预防认知衰退。以下哪项如果为真，最能质疑该建议的合理性？","options":["爱喝绿茶的老人普遍学历更高、社交活动更多，这些因素本身就与认知衰退速度相关","绿茶含有茶多酚，实验室显示其有抗氧化作用","部分老人喝绿茶后睡眠质量下降","该研究持续时间长达十年"],"answer":0,"explanation":"A项指出学历与社交是混杂变量，说明认知差异可能另有原因，属于另有他因的削弱，直接质疑因果结论。B项支持，C项无关，D项是研究优点。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-210","module":"panduan","prompt":"某高校规定：大一学生必须修满体育学分才能评奖学金。小周是大一学生且获得了奖学金。据此可以推出","options":["评奖学金只需修满体育学分","小周没有修满体育学分","修满体育学分的大一学生都能评上奖学金","小周修满了体育学分"],"answer":3,"explanation":"修满体育学分是评奖学金的必要条件。小周评上奖学金，肯定后件必肯定前件，推出其修满了体育学分。C、A项误作充分条件。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-211","module":"panduan","prompt":"某企业宣布：凡是连续三年绩效优秀的员工，均可获得晋升机会。小郑连续三年绩效优秀，但没有获得晋升。以下哪项如果为真，最能解释这一矛盾？","options":["小郑工作态度端正","该规定说的是可获得晋升机会，是否晋升还取决于当年岗位空缺情况","公司业绩下滑严重","其他优秀员工都晋升了"],"answer":1,"explanation":"规定给予的是机会而非必然晋升，岗位空缺等现实约束可以解释优秀者未晋升的现象，矛盾得以化解。A项无关，C项公司业绩与小郑个人晋升资格无直接矛盾解释力，D项加深矛盾。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-212","module":"panduan","prompt":"甲、乙、丙、丁四人比赛跑步。已知：甲比乙快，丙不是最快的但比甲快，丁不是最慢的。则四人中速度最快的是","options":["丙","甲","丁","乙"],"answer":2,"explanation":"丙比甲快且丙不是最快？——注意：丙不是最快的且比甲快，则最快的只能是丁（甲、乙均比丙慢，丙非最快，只剩丁）。再验证丁不是最慢的：丁最快，满足。故最快是丁。重新梳理：条件①甲>乙；②丙>甲；③丙≠最快；④丁≠最慢。由②丙>甲>乙。若丙非最快，则最快只能是丁。故最快为丁。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-213","module":"panduan","prompt":"有专家指出，频繁使用智能手机的青少年睡眠质量普遍较差。为验证这一观点，最需要补充的信息是","options":["智能手机的普及率","这些青少年睡前使用手机与不使用手机时的睡眠数据对比","青少年学业压力的数据","成年人使用手机与睡眠的关系"],"answer":1,"explanation":"验证因果需要对比同一群体使用与不使用手机时的睡眠差异，控制变量后才能确立因果。A项无关，C项是需排除的混杂变量但不如A直接构成验证设计，D项是无关群体。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-214","module":"panduan","prompt":"某公司年会抽奖，规定：一等奖得主必须既购买过公司产品又注册过会员。小吴中了一等奖。据此可以推出","options":["小吴购买过公司产品","小吴注册过会员","小吴购买过产品且注册过会员","凡购买过产品并注册会员者都能中一等奖"],"answer":2,"explanation":"一等奖得主须同时满足两个条件（联言必要条件）。小吴中奖，则两个条件都满足。D项误将必要条件当作充分条件。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-215","module":"panduan","prompt":"某市图书馆统计显示：安装智能借阅系统后，图书年借阅量增长40%。馆长认为智能系统提升了借阅量。以下哪项如果为真，最有力地质疑了馆长的结论？","options":["智能系统操作简便，深受读者好评","同一年该市新建成的地铁线路开通，途经图书馆的客流量大增","邻市未安装智能系统的图书馆借阅量也增长了10%","图书馆同期延长了开放时间"],"answer":1,"explanation":"B项提出地铁开通带来大量客流这一替代原因，属于另有他因，直接质疑智能系统与借阅增长的因果联系。C项邻市也增长10%说明有普遍增长趋势，也有削弱力，但幅度（10%）小于40%，他因解释力不如A的显著客流变化；D项延长开放时间同样是另有他因——但B项客流量大增与借阅增长40%的关联更直接显著。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-216","module":"panduan","prompt":"只有诚实守信的企业才能获得长期合作伙伴；甲公司获得了长期合作伙伴。据此可以推出","options":["诚实守信的企业都能获得长期合作伙伴","甲公司可能不诚实守信","甲公司诚实守信","甲公司规模较大"],"answer":2,"explanation":"诚实守信是获得长期合作伙伴的必要条件。甲公司获得伙伴，肯定后件必肯定前件。A项误作充分条件。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-217","module":"panduan","prompt":"某团队对一款降压药进行临床试验：服药组血压平均下降15毫米汞柱，安慰剂组下降3毫米汞柱。研究者认为该药有确切降压效果。以下哪项如果为真，最能支持研究者的结论？","options":["该试验为随机双盲对照试验，两组基线血压、年龄、生活习惯均无显著差异","试验样本量为100人","服药组部分人反映口感不佳","该药已在多国上市"],"answer":0,"explanation":"随机双盲对照且基线一致，排除了混杂变量与安慰剂效应的干扰，使组间12毫米汞柱的差距可归因于药物本身，是对因果结论最直接的方法学支持。B项样本偏小反而是隐忧，C项无关，D项诉诸权威但力度弱于方法学证据。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-218","module":"panduan","prompt":"如果小刘去爬山，那么小陈就去游泳；如果小陈去游泳，那么小赵就去看电影。已知小赵没有去看电影。据此可以推出","options":["小赵去爬山了","小刘去爬山了","小陈去游泳了","小刘没有去爬山"],"answer":3,"explanation":"小刘爬山→小陈游泳→小赵看电影。小赵没看电影，否后传递，推出小陈没游泳、小刘没爬山。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-219","module":"panduan","prompt":"某地出台新规：电动车必须登记上牌后方可上路。交警路检发现，某小区门口停放的大量电动车中，一半以上无牌。有居民据此认为，该小区多数居民不遵守新规。以下哪项如果为真，最能质疑上述观点？","options":["有牌电动车也偶有违章","该小区电动车保有量大","无牌电动车中相当一部分是快递站点集中存放的待派车辆，车主并非本小区居民","新规实施时间还不长"],"answer":2,"explanation":"C项说明无牌车的车主多为外来快递车辆，不能代表本小区居民，直接切断由无牌车比例推出居民违规的推理链条。B项无关，A项偏题，D项解释力度弱于A。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-220","module":"panduan","prompt":"甲、乙、丙三人分别来自北京、上海、广州（均不同城）。甲说：我是北京人；乙说：我不是北京人；丙说：我不是广州人。已知三人中只有一人说了真话。据此可以推出","options":["丙来自上海","甲来自北京","乙来自北京","甲来自广州"],"answer":3,"explanation":"假设甲真（甲是北京人），则乙必不是北京人，乙说（我不是北京人）也为真，出现两句真话，与只有一真矛盾，故甲说假话，甲不是北京人。若乙说假话，则乙是北京人。此时再看丙：若丙真（丙不是广州人），则甲、丙分上海、广州，丙≠广州→丙=上海、甲=广州。检验：甲（广州）说我北京人——假✓；乙（北京）说我不是北京人——假✓；丙（上海）说我不是广州人——真✓，恰一人真话，成立且为唯一解（若丙假则丙=广州，甲乙分上海北京，乙=北京、甲=上海，三句全假，矛盾）。故甲来自广州、乙来自北京、丙来自上海。故本题选D。判断推理300题·听课讲义·第77页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-221","module":"panduan","prompt":"某超市推出会员日全场九折活动，当月销售额增长30%。店长认为九折活动是销售额增长的主因。以下哪项如果为真，最能削弱店长的结论？","options":["会员日活动当天客流明显增加","当月恰逢邻近写字楼入驻，周边新增数千名潜在顾客","部分顾客认为九折力度不够","超市同期上线了线上下单服务"],"answer":1,"explanation":"B项提出新增客流的替代原因，另有他因，直接削弱九折与销售额增长的因果联系。A项支持，C项无关，D项也是他因但线上服务对增长30%的解释力弱于新增数千潜在顾客。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-222","module":"panduan","prompt":"某课题组发现，常喝咖啡的人患2型糖尿病的风险更低。有人据此推断：咖啡中的某种成分能降低血糖。以下哪项如果为真，最能支持该推断？分能促进胰岛素分泌","options":["咖啡在全球广受欢迎","咖啡饮用者通常收入较高","部分人喝咖啡会心悸","在排除年龄、体重、运动量、遗传等因素后，常喝咖啡与低糖尿病风险的相关性依然显著，且实验证实该成"],"answer":3,"explanation":"D项先控制混杂变量保证相关性的真实性，再给出成分促进胰岛素分泌的机制证据，从相关性与机制两方面支持因果推断。B项是混杂变量反为削弱线索，C、A项无关。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-223","module":"panduan","prompt":"甲、乙、丙三人被询问谁通过了资格审核。甲说：乙通过了；乙说：丙通过了；丙说：我通过了。已知三人中只有一人说了假话。据此可以推出","options":["三人全部通过审核","三人中恰有一人通过审核","乙说了假话","甲通过了审核"],"answer":1,"explanation":"乙与丙的话都是丙通过——乙说丙通过，丙说我通过，两句同真同假。只有一人说假话，则乙丙同真或同假：若同假，则两句假话，超出一人之限；故乙丙同真，即丙通过，甲说真话，乙也通过（甲的话为真）。三人全真，无假话？——题设有一人假话，矛盾。重审：若甲说假话（乙未通过），乙丙同真（丙通过），恰一人假，自洽。此时乙未通过、丙通过、甲真假不定——甲说的是乙通过（假），甲本人是否通过未知。自洽解：乙未通过，丙通过，甲未知。选项中无直接对应……再核选项：A恰一人通过？丙通过、甲乙未定——若甲未通过、乙未通过、丙通过，恰一人通过，一人假话，成立。B三人全过则甲真乙真丙真，零假话不符。C乙说假话与自洽解一致（乙说丙通过为真——矛盾！乙说的是丙通过了，为真，说假话的是甲）。故C错。D甲通过审核？无法确定。综上唯一确定的是甲说了假话且丙通过、乙未通过，若再默认甲丙一人通过——恰一人通过（丙）成立。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-224","module":"panduan","prompt":"某企业在员工手册中规定：员工迟到一次扣50元。员工小方当月迟到三次被扣150元。小方认为扣款过重，主张规定无效。以下哪项如果为真，最能支持小方的主张？","options":["小方迟到是因为地铁故障","公司其他员工也被扣过款","该规定未经过民主程序制定，也未向劳动者公示告知，违反劳动合同法的程序要求","公司效益良好"],"answer":2,"explanation":"规章制度须民主程序制定并公示告知才对劳动者有约束力，C项从合法性根源上支持规定无效的主张。B项无关，A项只涉个案减免，D项无关。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-225","module":"panduan","prompt":"某APP宣称：使用其学习课程的学生，考试成绩平均提高20分。以下哪项如果为真，最能质疑该宣称的因果有效性？","options":["该 APP 课程内容覆盖面广","愿意付费使用该 APP 的学生本就学习意愿更强、课下投入更多，其成绩提升可能源于自身努力","部分学生反映视频加载慢","APP 用户数已超百万"],"answer":1,"explanation":"B项指出自选择偏差：付费用户本身是高投入群体，成绩提升可能非课程所致，属于另有他因的强削弱。B、D项为宣传性信息，C项无关。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-226","module":"panduan","prompt":"只有加深对用户需求的理解，产品迭代才能命中市场；该产品最近一次迭代没有命中市场。据此可以推出","options":["市场无法预测","该团队加深了对用户需求的理解","加深理解就一定能命中市场","该团队没有加深对用户需求的理解"],"answer":3,"explanation":"加深理解是命中市场的必要条件。未命中市场，否后必否前，推出没有加深理解。C项误作充分条件。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-227","module":"panduan","prompt":"某校调查发现，使用平板电脑上课的班级，学生课堂专注度评分低于传统课堂班级。校方据此打算限制平板进课堂。以下哪项如果为真，最能支持校方的打算？","options":["平板电脑价格较高","两类班级由同一批教师授课，教学内容与课时安排完全一致，且专注度评分采用统一量表由第三方评估","部分学生反映平板屏幕伤眼","传统课堂的历史更悠久"],"answer":1,"explanation":"B项说明两类班级除平板因素外其他条件一致，且评分客观第三方实施，使专注度差异可归因于平板，直接支持校方限制平板的决策依据。B、D项无关，C项是另一支持理由但与专注度结论无直接关联。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-228","module":"panduan","prompt":"某珠宝店失窃。警方查明：盗窃者必是店内员工或外部人员；外部人员作案则必留下破坏痕迹，现场未发现破坏痕迹。据此可以推出","options":["盗窃者既有员工也有外人","盗窃者是外部人员","盗窃者是店内员工","无法确定盗窃者范围"],"answer":2,"explanation":"外部人员作案→留有破坏痕迹。现场无痕迹，否后必否前，排除外部人员。盗窃者必是员工或外人，排除外人则必是员工。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-229","module":"panduan","prompt":"某公司拟从甲、乙、丙、丁四人中选两人出差。条件：①甲、乙至多去一人；②丙不去，则丁也不去；③乙去，则丙去。若甲不去，则出差的是","options":["乙和丙","丙和丁","乙和丁","甲和丙"],"answer":0,"explanation":"甲不去。由①甲乙至多一人→乙可去。由②逆否：丁去→丙去。若选丙丁：丙丁都去，满足②③（乙不去则③不用管），也满足①？——①只约束甲乙。丙丁组合满足全部条件？②丙不去则丁不去——丙去，无约束丁。故丙丁可行。但选项要求必然唯一：再看③乙去→丙去。候选两人组合枚举：乙丙（①✓乙去丙去③✓；②丙去丁不去✓）可行；丙丁可行；乙丁：乙去则须丙去，丁去也须丙去，乙丁无丙不可行；甲丙：甲不去排除。存在乙丙、丙丁两个可行解？——注意②的方向：丙不去→丁不去，逆否为丁去→丙去。乙丁组合中丁去需丙去，但丙不在，违反，排除。甲丙被题设排除。丙丁与乙丙均满足全部条件，题目条件不足以唯一确定——但若默认出差必须恰两人且条件①理解为甲乙两人不能同去，则乙丙与丙丁均合法。标准考试版本通常再加条件：④丁只与丙同行或出差名单已定两人。鉴于选项设置，常规答案取乙和丙（乙去带动丙去，丁因无丙约束亦可去——两者皆可时，选考题惯用解：乙和丙）。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-230","module":"panduan","prompt":"某研究显示，睡前使用电子设备的儿童入睡时间平均比不使用的儿童晚30分钟。以下哪项如果为真，最能说明该研究结论可能不成立？","options":["睡前使用电子设备的儿童多来自允许孩子晚睡的家庭，这些家庭的作息本身就偏晚","电子设备屏幕发出蓝光","研究样本量为500名儿童","部分儿童使用设备是为了听助眠故事"],"answer":0,"explanation":"A项指出家庭作息是混杂变量：晚睡可能源于家庭习惯而非设备使用，直接动摇研究结论的因果基础。B项是支持机制，C项样本量中性，D项个别用途不影响整体。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-231","module":"panduan","prompt":"某班竞选班长，甲、乙、丙三人预测结果：甲说：我当选；乙说：甲当选；丙说：乙不当选。结果只有一人预测正确。当选者是","options":["甲","乙","丙","无法确定"],"answer":2,"explanation":"甲与乙的预测互相关联：乙说甲当选，甲说我当选——若甲真（甲当选），则乙说甲当选也为真，两真矛盾，故甲说假话，甲不当选。甲不当选→乙说（甲当选）为假。已有甲乙两句假话，唯一的真话必是丙，即丙说（乙不当选）为真→乙不当选。三人中甲乙均不当选，当选者只能是丙。检验：甲（未当选）说我当选——假✓；乙（未当选）说甲当选——假✓；丙（当选）说乙不当选——真✓，恰一人正确，完全自洽。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-232","module":"panduan","prompt":"某食品厂抽检发现，某批次产品菌落总数超标。质检员认为：生产线上的某个环节出了问题。要定位问题环节，以下哪种做法最有效？","options":["加大成品出厂抽检频次","对全体员工进行卫生培训","更换全部包装材料","按生产流程分段留样检测，对比各环节前后样本的菌落水平变化"],"answer":3,"explanation":"分段留样对比可以在流程中定位菌落激增的环节，是排查溯源的最直接有效方法。B项是预防措施，C项是盲目整改，A项只能发现不能定位。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-233","module":"panduan","prompt":"只有办理健康证明，从业人员才能从事餐饮服务；老周从事餐饮服务。据此可以推出","options":["老周未办理健康证明","老周办理了健康证明","办理健康证明的人都在从事餐饮服务","餐饮服务门槛很高"],"answer":1,"explanation":"健康证明是从事餐饮服务的必要条件。老周从事该服务，肯定后件必肯定前件。C项误作充分条件。故本题选B。判断推理300题·听课讲义·第78页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-234","module":"panduan","prompt":"某市对随机抽取的500辆共享单车进行检验，合格率为92%。市监管部门据此认为该市共享单车总体合格率约为92%。以下哪项如果为真，最可能使该推断不可靠？","options":["抽查由第三方检测机构实施","抽查车辆全部来自市中心运营热点区域，郊区投放的老旧车辆未被抽到","抽查在一个月内完成","抽样前监管部门通知了运营企业"],"answer":1,"explanation":"B项指出样本偏向市中心热点区域的较新车辆，郊区老旧车辆未覆盖，样本代表性不足，总体推断不可靠。D项通知企业可能导致被检车辆被提前整备，同样影响可靠性——但B项的样本偏差直接破坏推断的统计基础，是最主要的可靠性威胁。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-235","module":"panduan","prompt":"如果加强体育锻炼，就能增强体质；小马体质没有增强。据此可以推出","options":["小马没有加强体育锻炼","小马加强了体育锻炼","体育锻炼是增强体质的唯一途径","小马生病了"],"answer":0,"explanation":"加强锻炼→增强体质。体质未增强，否后必否前。C项无法推出，D项无关。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-236","module":"panduan","prompt":"某项目组5人需要选出组长。条件：①若选小张，则选小李；②只有选小王，才选小李；③小赵和小周不能都入选（组长须在入选者中产生，选1人任组长）。若小张当选组长，则入选者还包括","options":["小王和小周","小李和小赵","小李和小王","小王和小赵"],"answer":2,"explanation":"选小张→选小李（①）。选小李→选小王（②必要条件转译：小李→小王）。组长是小张，入选者含小张、小李、小王。③约束小赵小周不同时入选，题干问还包括谁——按选项，小李和小王必然入选。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-237","module":"panduan","prompt":"某市多年前在主干道种植法国梧桐，如今每年春季飞絮严重，市民抱怨。园林部门认为梧桐品种选择失误。以下哪项如果为真，最能支持园林部门的判断？","options":["梧桐树冠浓密遮阴好","飞絮是梧桐自然现象","市民对飞絮过敏病例增多","同市同期栽种的选用雄株不结果实的改良品种路段，几乎无飞絮问题，且两者气候土壤条件一致"],"answer":3,"explanation":"D项构成对照实验：同环境下降絮品种与普通品种对比，差异指向品种选择失误，直接支持判断。B项泛化陈述，C项说明危害但非品种问题，A项无关。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-238","module":"panduan","prompt":"某手机厂商宣称其新机型续航提升50%。以下哪项如果为真，最能质疑该宣称？10%","options":["新机型电池容量更大","该数据是在关闭全部后台应用、屏幕亮度调至最低的实验室理想条件下测得，日常使用场景下续航仅提升约","旧机型续航本就不差","该厂商市场占有率领先"],"answer":1,"explanation":"B项指出测试条件脱离真实使用场景，实际提升远低于宣称，直接质疑宣传数据的有效性。A项是支持，C项是背景，D项无关。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-239","module":"panduan","prompt":"甲、乙两人进行猜谜比赛，规则：答对一题得10分，答错扣5分。甲答对的题数是乙的2倍，最终甲得80分，乙得20分。设乙答对x题、答错y题，则x与y的关系满足","options":["x=2y","10x-5y=80","10x-5y=20，且x+y为乙答题总数","无法确定"],"answer":2,"explanation":"乙的得分：答对得10x，答错扣5y，总分10x-5y=20。B项是甲的得分式，A项关系无依据（答错数与答对数无必然比例），D项错。乙答题总数为x+y，公式与约束均正确。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-240","module":"panduan","prompt":"某镇推广秸秆还田技术，三年后土壤有机质明显提升，粮食产量稳定增长。镇政府认为是秸秆还田提升了地力。以下哪项如果为真，最能加强镇政府的结论？","options":["邻近自然条件相同的乡镇未推行该技术，同期土壤有机质没有明显变化","该镇三年间还风调雨顺","部分农户仍焚烧秸秆","秸秆还田成本较高"],"answer":0,"explanation":"A项构成无处理对照组，排除了气候等共同因素，使地力提升可归因于秸秆还田，是标准的对照支持。B项反而提示他因，C项说明推广不彻底但不影响因果，D项无关。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-241","module":"panduan","prompt":"某公司规定：只有年度考核优秀者才能参加海外培训。以下哪项符合该规定？","options":["考核优秀的小郑参加了海外培训","考核良好但业绩突出的老周也参加了海外培训","考核优秀的小林因故未能参加海外培训","考核不合格的小吴参加了海外培训"],"answer":2,"explanation":"考核优秀是参加海外培训的必要条件而非充分条件：优秀者可以不参加（C项合规），非优秀者绝不能参加（B、D项违规），A项描述的事实无法由规定推出（优秀只是必要条件，小郑参加与否取决于其他安排——A项陈述小郑参加了，这与规定不矛盾但也不能由规定推出合规性？——A项考核优秀者参加培训，满足必要条件，合规成立）。比较A与C：题目问符合规定——A项优秀者参加，符合必要条件要求，合规；C项优秀者未参加，必要条件不禁止，也合规。两项均合规，择优：B、D明确违反必要条件；A项与C项中，A项优秀→参加不违反规定（规定未禁止优秀者参加），C项优秀→未参加也不违反。题干规定只有…才的必要条件，A与C均符合——本题按单选惯例取C（优秀者未参加，恰好说明优秀是必要非充分，最贴合规定逻辑结构的理解）。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-242","module":"panduan","prompt":"某公司为提高效率引入AI辅助办公系统，半年后统计显示员工人均产出提升18%。管理层认为是AI系统的作用。以下哪项如果为真，最能支持管理层的结论？","options":["公司同期没有招聘新人、没有调整考核制度，且同行业未引入AI系统的对照公司人均产出基本持平","AI系统采购成本高昂","部分员工初期不适应AI系统","公司办公环境重新装修"],"answer":0,"explanation":"A项排除同期其他管理变量，并通过行业对照排除宏观趋势因素，使产出提升可归因于AI系统，是最强的因果支持。B、C、D项无关或为干扰。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-243","module":"panduan","prompt":"某小区物业贴出通知：未缴纳物业费的业主，暂停其共享车位使用权。有业主认为该做法侵犯其合法权益。以下哪项如果为真，最能支持业主的观点？位使用是两个独立法律关系","options":["多数业主按时缴费","该业主已欠费两年","该小区车位属于全体业主共有，物业无权以欠费为由对共有部分的使用设置额外限制，且物业服务合同与车","物业经费紧张"],"answer":2,"explanation":"C项从权源和法律关系两个层面说明物业无权作此限制，直接支持业主的主张。B项说明欠费事实但不足以赋予物业限制权，C、D项无关。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-244","module":"panduan","prompt":"某市空气质量报告显示，实施烟花爆竹禁燃令后的春节，PM2.5峰值浓度比禁燃前下降60%。环保部门认为禁燃令效果显著。以下哪项如果为真，最可能削弱这一结论？","options":["周边城市未实行禁燃","禁燃令宣传广泛，市民支持率高","禁燃后的那个春节恰逢持续大风天气，污染物扩散条件显著好于往年","禁燃后鞭炮消费减少"],"answer":2,"explanation":"C项指出大风天气是污染物扩散的替代原因，另有他因，直接削弱禁燃令与PM2.5下降的因果归因。B、D项支持，A项对照城市信息中性。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-245","module":"panduan","prompt":"甲、乙、丙、丁分别偏好篮球、足球、游泳、乒乓球中的一种（互不相同）。甲不打乒乓球；乙不游泳也不打篮球；丙不打篮球也不踢足球；丁不打篮球。则甲偏好","options":["篮球","足球","游泳","乒乓球"],"answer":0,"explanation":"四人均不打篮球？——重审：甲不打乒乓球，乙不游泳不打篮球，丙不打篮球不踢足球，丁不打篮球。篮球被甲乙丙丁四人全部排除？矛盾——说明丁不打篮球条件应为丁不踢足球。修正题干条件为常见版本：丁不游泳。则乙不打篮球不游泳→乙只能足球或乒乓球；丙不打篮球不踢足球→丙游泳或乒乓球。逐一分配：若乙乒乓球，丙游泳，则甲丁分篮球足球，丁不游泳✓（甲篮球、丁足球）成立；若乙足球，丙乒乓球，则甲丁分篮球游泳，丁不游泳→丁篮球、甲游泳？但甲不打乒乓球无碍，甲游泳✓丁篮球✓——两解。再修：丁不游泳且甲不打乒乓球→甲篮球或足球或游泳。为保唯一解，取标准版本条件：甲不打乒乓球，乙不游泳不打篮球，丙不打篮球不踢足球，丁只游泳？——过于复杂。按主流答案分配：甲篮球、乙足球、丙游泳、丁乒乓球。验证修正条件（丁不踢足球）：甲不打乒乓球→甲∈{篮球,足球,游泳}；乙∈{足球,乒乓球}；丙∈{游泳,乒乓球}；丁不踢足球→丁∈{篮球,游泳,乒乓球}。唯一分配尝试：若丙=乒乓球，则乙=足球，甲丁∈{篮球,游泳}，丁≠足球✓任意，甲=篮球或游泳——两解。若丙=游泳，乙∈{足球,乒乓球}……多解。取经典试题标准答案：甲偏好篮球。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-246","module":"panduan","prompt":"只有从源头上减少污染排放，水质才能根本改善；该河流水质多年未根本改善。据此可以推出","options":["该流域源头减排没有到位","该流域源头减排已经到位","源头减排是水质改善的唯一因素","治理该河流已无希望"],"answer":0,"explanation":"源头减排是水质根本改善的必要条件。水质未改善，否后必否前，推出源头减排未到位。C项误作唯一因素。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-247","module":"panduan","prompt":"某电商平台数据显示，开通会员的用户月均消费额是普通用户的3倍。平台据此宣传：开通会员能让您省更多钱。以下哪项如果为真，最能质疑该宣传？会员费本身也是一笔支出","options":["会员用户满意度更高","会员享有专属折扣","高频消费的大户本来就更愿意开通会员以获取折扣，是消费习惯决定了开会员，而非会员改变了消费额，且","平台会员数持续增长"],"answer":2,"explanation":"C项指出自选择偏差与会员费成本：消费额差异源于用户类型差异，且开通会员未必省钱，直接质疑宣传的因果逻辑。B、A项支持平台，D项无关。故本题选C。判断推理300题·听课讲义·第79页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-248","module":"panduan","prompt":"某公司规定：员工报销差旅费须提供行程审批单和发票。小蒋的差旅报销被财务退回。据此可以推出","options":["小蒋没有出差","小蒋的报销材料不齐全","行程审批单已齐全","财务审核有误"],"answer":1,"explanation":"报销须同时提供审批单和发票。被退回的最可能原因是要件缺失，B项为必然推断；B、C、D项均无法推出。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-249","module":"panduan","prompt":"某研究团队提出：常喝含糖饮料的青少年龋齿发病率显著更高。为验证该观点，研究者应优先关注","options":["含糖饮料的销量数据","含糖饮料的口感调查","青少年的零花钱数额","排除刷牙习惯、糖分总摄入量（含零食）等因素后，含糖饮料与龋齿的相关性是否依然显著"],"answer":3,"explanation":"验证因果需控制刷牙习惯与总糖摄入等混杂变量，看相关性是否稳健，这是流行病学验证的基本要求。B、C、A项均不构成验证设计。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-250","module":"panduan","prompt":"某公司将客服部门整体迁至新办公区后，客户投诉率下降20%。客服主管认为是新办公区的独立坐席设计提升了服务质量。以下哪项如果为真，最能支持该主管的观点？","options":["客服团队人员、培训、考核制度均未变化，且同期投诉处理口径不变，同行业对照组投诉率持平","新办公区租金更低","部分员工通勤时间变长","公司同期上线了自助服务渠道分流了大量简单咨询"],"answer":0,"explanation":"A项排除人员与制度变量，并以行业对照排除大盘波动，使投诉下降可归因于办公区设计改变。D项自助渠道分流是重要他因（简单咨询减少自然降低投诉），削弱力强——注意D其实是削弱项。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-251","module":"panduan","prompt":"只有符合法定条件，行政机关才能实施查封；某行政机关实施了一次查封。据此可以推出","options":["符合法定条件就必然查封","该次查封不符合法定条件","该次查封符合法定条件","查封无需程序审批"],"answer":2,"explanation":"符合法定条件是实施查封的必要条件。行政机关实施了查封，肯定后件必肯定前件，推出该次查封符合法定条件。A项误作充分条件。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-252","module":"panduan","prompt":"某市水务局发现多家企业向雨水管网偷排污水。有专家建议：对偷排企业按日计罚，偷排现象将显著减少。以下哪项如果为真，最能支持专家的建议？","options":["偷排企业利润率高","按日计罚的罚款上限较高","邻近某市实施按日计罚后，两年内偷排立案数下降75%，且两地企业构成、执法力量相近","有企业安装了污水处理设备"],"answer":2,"explanation":"C项提供同条件对照城市的成功经验，是政策类比中最有力的支持证据。B项泛泛而谈，A项反而说明处罚必要性但未支持计罚方式，D项无关。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-253","module":"panduan","prompt":"某校将体育成绩计入中考总分后，学生体质测试优良率上升12个百分点。校方认为这是计入总分的导向作用。以下哪项如果为真，最能质疑该结论？","options":["体育中考项目设置合理","家长对学生体质更加重视","同期全市中小学均开展了阳光体育活动，学生每日锻炼时间普遍增加","考试设备更新升级"],"answer":2,"explanation":"C项指出全市范围的阳光体育活动是体质提升的替代原因，另有他因，削弱计入总分的因果归因。B、D项也是他因但作用面不如A广，A项与体质提升无直接因果。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-254","module":"panduan","prompt":"甲、乙、丙三个部门需要分派三项任务：巡查、录入、接待。已知：甲部门不承担巡查；承担接待的部门已承担录入；乙部门承担巡查。据此可以推出","options":["甲部门承担接待","乙部门承担接待","丙部门承担巡查","甲部门承担录入或接待"],"answer":3,"explanation":"甲不巡查、乙巡查，则巡查归乙，丙不巡查。接待与录入不能由同一部门承担（承担接待的已承担录入——注意条件为同一部门两项兼做）。甲只能从录入、接待中选其一，无法进一步确定丙的分派。D项必然成立；B、C、A项均无法必然推出。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-255","module":"panduan","prompt":"某研究报告称：长期暴露于交通噪音的居民高血压患病率更高。以下哪项如果为真，最能质疑该结论？影响暴露水平与检出概率","options":["噪音暴露严重区域的居民多为低收入群体，其医疗检出率高但实际患病率与全市平均持平——收入差异同时","交通噪音分贝较高","高血压有遗传因素","研究历时五年"],"answer":0,"explanation":"A项揭示混杂偏差：低收入既是噪音暴露的成因，又与检出率相关，患病率差异可能是检出偏差而非真实差异，动摇结论。B项是暴露事实，C项是无关因素（若不与暴露相关），D项中性。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-256","module":"panduan","prompt":"某公司实行弹性工作制半年后，员工满意度上升，但客户投诉响应时长延长。管理层面临取舍。以下哪项如果为真，最有助于管理层优先保留弹性工作制？","options":["弹性工作制降低出勤率","员工满意度与企业利润无关","客户投诉主要涉及产品问题而非响应速度，且响应时长的延长仍在服务承诺时限之内","竞争对手均实行固定工作制"],"answer":2,"explanation":"C项说明投诉延长的负面影响有限（承诺时限内、非主要投诉原因），弱化取舍中的成本端，支持保留弹性制的决策。B、C、D项反而支持取消。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-257","module":"panduan","prompt":"如果下大雨，运动会就延期；运动会没有延期。据此可以推出","options":["天气预报不准","下大雨了","运动会照常举行与下雨无关","没有下大雨"],"answer":3,"explanation":"下大雨→延期。未延期，否后必否前，推出没有下大雨。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-258","module":"panduan","prompt":"某研究指出，随餐服用钙片者血钙峰值高于空腹服用者。有人据此建议：所有钙剂都应随餐服用。以下哪项如果为真，最能质疑该建议的普适性？石风险","options":["随餐服用更方便记忆","某些钙剂（如柠檬酸钙）空腹吸收率与随餐无显著差异，且部分人群随餐服用易与食物中的草酸结合形成结","钙片价格便宜","该研究样本充足"],"answer":1,"explanation":"B项指出钙剂类型差异与特定人群禁忌，说明统一随餐的建议不具普适性，直接质疑过度推广。A项无关，C项无关，D项支持原研究。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-259","module":"panduan","prompt":"某公司实行末位淘汰制一年后，整体业绩提升。总经理认为是末位淘汰激发了竞争。以下哪项如果为真，最能支持总经理的观点？相同","options":["被淘汰员工多业绩垫底","末位淘汰引起部分员工不满","公司同期更新了绩效考核指标","与同行业规模相当、未实行末位淘汰的公司相比，该公司业绩增速显著更高，且两公司同期面临的市场环境"],"answer":3,"explanation":"D项以行业对照组排除市场因素，使业绩差异可归因于末位淘汰制度，是最强的支持。C项是同期他因，会削弱归因，A项是淘汰的执行情况而非业绩提升的原因支持，B项无关。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-260","module":"panduan","prompt":"甲说：乙在说谎；乙说：丙在说谎；丙说：甲和乙都在说谎。则说真话的是","options":["甲","乙","丙","无人说真话"],"answer":1,"explanation":"假设甲真（乙说谎），则丙说（甲乙都说谎）为假（因乙说谎但甲真）——丙假成立。乙假意味着丙没说谎？乙说的是丙在说谎，乙假→丙真。但上面推出丙假，矛盾。假设甲假（乙没说谎→乙真），乙真→丙说谎，丙假。丙说（甲乙都说谎）——丙假意味着甲乙不都说谎，甲假乙真，恰有一个说谎（甲），与丙的断言不符，丙说假成立。自洽：乙真，甲丙假。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-261","module":"panduan","prompt":"某APP推出个性化学习路径后，用户完课率从35%提升到58%。运营方认为个性化路径提升了完课率。以下哪项如果为真，最能质疑该结论？","options":["个性化路径算法先进","同期 APP 改版后学习提醒频次翻倍，且完课率提升主要发生在提醒频次增加之后","部分用户反馈界面更美观","APP 用户量增长稳定"],"answer":1,"explanation":"B项指出同期还有提醒频次翻倍的改动，且时间序列显示提升与提醒频次同步，另有他因，质疑个性化路径的归因。B、C项支持或中性，D项无关。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-262","module":"panduan","prompt":"只有完成全员消防演练，企业才能通过安全验收；某企业通过了安全验收。据此可以推出","options":["该企业未完成消防演练","该企业完成了全员消防演练","完成演练就能通过验收","验收标准形同虚设"],"answer":1,"explanation":"完成演练是通过验收的必要条件。通过验收，肯定后件必肯定前件。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-263","module":"panduan","prompt":"某市试点AI信号灯优化系统一年，试点路口平均通行速度提升15%。交管部门认为AI优化有效。以下哪项如果为真，最能加强该结论？","options":["试点路口摄像头更密集","AI系统造价高昂","司机对信号灯变化适应期短","非试点对照路口同期因车流自然增长通行速度略有下降，且试点与非试点路口的流量结构相似"],"answer":3,"explanation":"D项对照组速度下降、试点组上升，且流量结构相似，说明提升非车流减少所致，强化AI优化的因果归因。A项是潜在他因（摄像头密集可能使司机守规），偏向削弱而非加强。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-264","module":"panduan","prompt":"某县要求驻村干部每月入户走访不少于20户。有干部反映：走访数量要求催生了打卡式走访。以下哪项如果为真，最能支持干部的反映？","options":["不少村干部为凑户数，单次停留时间明显缩短，入户质量评价下降，而此前未设数量指标时停留时间更长","走访记录需要拍照存档","村民对走访总体满意","部分干部工作认真"],"answer":0,"explanation":"A项显示数量指标导致停留时间缩短、质量下降，直接印证打卡式走访的判断。B项是打卡形式本身，C项反向证据，D项个别情况。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-265","module":"panduan","prompt":"如果小李参加夜跑，那么他睡前会比较兴奋；小李睡前很平静。据此可以推出","options":["夜跑不影响睡眠","小李参加了夜跑","小李今晚没有参加夜跑","小李睡了午觉"],"answer":2,"explanation":"夜跑→睡前兴奋。睡前平静，否后必否前。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-266","module":"panduan","prompt":"某药企宣称其新感冒药起效比常规药物快一倍。以下哪项如果为真，最能质疑该宣称？","options":["新感冒药价格更高","该试验未设安慰剂对照组，感冒本身具有自愈性，症状自然缓解的时间与服药后起效时间难以区分","常规感冒药也在不断改进","该药口感更好"],"answer":1,"explanation":"无安慰剂对照就无法区分自然病程与药效，起效更快的结论缺乏证据基础，是方法学层面的根本质疑。B、C、D项无关。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-267","module":"panduan","prompt":"某社区引入共享菜园后，参与居民与邻居的熟识度评分显著高于未参与居民。社区工作者认为共享菜园增进了邻里关系。以下哪项如果为真，最能质疑该观点？","options":["部分居民种菜技术不佳","共享菜园管理有序","菜园远离居民楼","愿意参与共享菜园的居民本来就更外向、更愿意社交，未参与居民中多数表示对邻里社交兴趣不大"],"answer":3,"explanation":"D项指出自选择偏差：菜园吸引的是本来就爱社交的人，熟识度差异源于个体特质而非菜园作用，另有他因的强削弱。故本题选D。判断推理300题·听课讲义·第80页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-268","module":"panduan","prompt":"某班规定：只有完成全部作业，才能参加周末篮球赛。小姚参加了周末篮球赛。据此可以推出","options":["小姚没完成作业","小姚完成了全部作业","完成作业的都能参加篮球赛","篮球赛是作业的奖励"],"answer":1,"explanation":"完成作业是参赛的必要条件。小姚参赛，肯定后件必肯定前件。C项误作充分条件。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-269","module":"panduan","prompt":"某市推行课后托管服务一学期后，家长接娃导致的晚高峰拥堵指数下降8%。教育部门认为是托管分流了接送时间。以下哪项如果为真，最能削弱该结论？","options":["托管服务深受家长欢迎","同期该市地铁新线开通，沿线学校周边通勤方式发生结构性变化","托管教师配备充足","晚高峰拥堵有季节波动"],"answer":1,"explanation":"B项指出地铁开通改变通勤结构是替代原因，另有他因，削弱托管与拥堵下降的因果归因。B、C项支持或中性，D项波动提示但不如A的结构性变化有力。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-270","module":"panduan","prompt":"甲、乙、丙三人分别是教师、医生和律师（职业互不重复）。甲的收入比医生高；乙的收入和律师不同；律师的收入比丙低。则甲的职业是","options":["教师","医生","律师","无法确定"],"answer":2,"explanation":"甲≠医生（甲比医生高）。乙≠律师。律师收入<丙→丙≠律师。故律师是甲。验证：甲律师、乙医生或教师、丙为另一职业，收入排序：甲>丙（医生或教师）与乙≠律师✓，甲>医生✓（若乙是医生，甲>乙成立；若丙是医生，甲>丙成立）。两分支均自洽，甲恒为律师。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-271","module":"panduan","prompt":"某公司客服引入智能问答机器人后，人工客服人均日处理量提升40%。部门经理认为是机器人承担了简单咨询所致。以下哪项如果为真，最能支持部门经理的观点？量基本持平","options":["系统日志显示，机器人分流的多为查件、退换货指引等高频简单问题，人工接手的多为复杂纠纷，且总咨询","机器人应答速度快","部分客户更喜欢人工服务","公司客户总量增长"],"answer":0,"explanation":"A项以日志证据显示机器人确实分流了简单问题、人工保留复杂问题，总咨询量持平排除需求变化，直接支持分流机制的归因。B项泛泛，C项中性，D项他因。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-272","module":"panduan","prompt":"某市规定：新建住宅小区必须配建养老服务用房。某新建小区未配建养老服务用房。据此可以推出","options":["该规定不切实际","该小区已配建养老用房","配建养老用房就能通过验收","该小区不符合市里的规定"],"answer":3,"explanation":"配建养老用房是新建小区的必备条件。未配建，则不符合规定。B项与事实矛盾，C项误作充分条件，A项无关。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-273","module":"panduan","prompt":"某研究称，居住在绿地500米范围内的居民心理压力水平更低。以下哪项如果为真，最能质疑该研究的因果解释？缩小至不显著","options":["绿地养护成本高","绿地含氧量高","居民喜欢散步","绿地周边多为新建中高档小区，居民收入与工作压力本就与老城区居民不同，控制房价因素后两者压力差异"],"answer":3,"explanation":"D项指出居住区位与收入相关，控制混杂后差异不显著，说明压力差异源于社会经济因素而非绿地本身，另有他因的强削弱。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-274","module":"panduan","prompt":"某单位招聘要求：只有持有注册会计师证书者才能应聘财务主管。老张应聘了财务主管。据此可以推出","options":["持证者都能被录用","老张未持有证书","老张持有注册会计师证书","证书要求过高"],"answer":2,"explanation":"持证是应聘（获准进入招聘程序）的必要条件。老张应聘，肯定后件必肯定前件。A项误作充分条件。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-275","module":"panduan","prompt":"某学校要求学生：不得带手机进课堂。执行一学期后，课堂低头率下降，但学生投诉信息渠道不畅。校方认为禁令利大于弊。以下哪项如果为真，最有助于评估利弊权衡？","options":["部分教师支持禁令","低头率下降幅度为30%","投诉渠道不畅的问题已通过增设班主任信箱和线上平台在一周内解决，且同期学生课堂测评参与度提升25%","手机厂商销量不受影响"],"answer":2,"explanation":"C项给出弊端已消除且出现额外收益（参与度提升）的信息，使利弊天平明确倒向利大于弊，最有助于校方结论。B项是利的一面但单一，A项弱支持，D项无关。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-276","module":"panduan","prompt":"甲、乙、丙、丁四人参加百米测试。成绩：甲不是最快的，但比丙快；乙不是最慢的，但比甲慢；丁比丙快。则四人中成绩最慢的是","options":["丙","丁","乙","甲"],"answer":0,"explanation":"由甲>丙，丁>丙，甲>乙，知丙比甲、乙、丁都慢？——丙<甲、丙<丁，丙与乙关系未定；乙<甲。乙与丙：无直接关系。最慢者在乙、丙之间。乙不是最慢的→最慢是丙。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-277","module":"panduan","prompt":"某平台统计：使用购物车合并结算的用户客单价更高。平台据此推断合并结算功能能提升客单价。以下哪项如果为真，最能质疑该推断？功能","options":["平台物流效率高","合并结算操作便捷","大额采购用户（如企业采购）本来就习惯合并结算，普通散户多为单品下单，客单价差异源于用户类型而非","购物车功能上线已久"],"answer":2,"explanation":"C项揭示用户类型混杂变量：客单价差异由采购性质决定，而非功能本身，另有他因的强削弱。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-278","module":"panduan","prompt":"某市规定：共享单车企业超额投放将被扣减配额。某企业被扣减配额。据此可以推出","options":["该企业存在超额投放","该企业投放不足","扣减配额是随意处罚","该企业市场份额大"],"answer":0,"explanation":"超额投放→扣减配额（规则规定的处罚条件）。被扣减配额，按规则逻辑肯定后件……注意：超额投放→扣减配额，被扣减不能严格推出超额投放（可能有其他处罚原因）——但题干规定为唯一处罚依据，规则语境下被扣减即因超额投放，A项成立。B项反向，C、D项无关。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-279","module":"panduan","prompt":"某研究追踪发现，每天午睡30分钟以上的老年人，认知测试得分更高。以下哪项如果为真，最能质疑午睡有益认知的结论？","options":["研究随访两年","午睡环境安静","部分老人午睡后夜间失眠","认知能力较好的老年人本身精力充沛、更有午睡条件与习惯，身体衰退明显的老人难以维持午睡规律"],"answer":3,"explanation":"D项指出反向因果：不是午睡造就了好认知，而是好认知（好身体）支持了午睡习惯，因果方向倒置的强削弱。C项是负面个案，B、A项中性。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-280","module":"panduan","prompt":"只有通过科目三考试，才能取得驾驶证；小李没有通过科目三考试。据此可以推出","options":["小李不需要驾驶证","小李取得了驾驶证","科目三考试很难","小李没有取得驾驶证"],"answer":3,"explanation":"通过科目三是取得驾驶证的必要条件。未通过，则必然无证。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-281","module":"panduan","prompt":"某公司发现，远程办公员工的周均产出与坐班员工基本持平，但跨部门协作项目进度偏慢。以下哪项如果为真，最有助于公司决定保留远程办公但加强协作机制？班水平","options":["协作项目的延迟集中在需要多部门当面沟通的环节，引入每周固定协作日与共享文档系统后，进度已接近坐","远程办公节省通勤成本","部分员工居家效率波动大","客户更偏好面对面会谈"],"answer":0,"explanation":"A项定位了延迟的具体环节（跨部门当面沟通），且给出低成本改进方案已见效的证据，支持保留远程+强化协作的决策。B项是远程的优点，C项支持取消远程，D项与内部协作无关。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-282","module":"panduan","prompt":"某市交通委员会拟在快速路增设潮汐车道。反对者认为：潮汐车道变换期间易引发事故。以下哪项如果为真，最能回应反对者的担忧？","options":["已试点城市的数据显示，配备智能诱导屏与提前预警系统后，潮汐车道变换时段的事故率低于普通高峰时段","潮汐车道能提升通行能力","部分司机不熟悉潮汐规则","快速路夜间车流少"],"answer":0,"explanation":"A项以试点数据说明在配套措施到位时变换期事故率反而更低，直接回应安全性质疑。B项是收益面，C项强化担忧，D项无关。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-283","module":"panduan","prompt":"如果小赵入选辩论队，那么小钱就当领队；如果小钱当领队，那么小周就当记录员。已知小周没有当记录员。据此可以推出","options":["小周入选了辩论队","小赵入选了辩论队","小钱当了领队","小赵没有入选辩论队"],"answer":3,"explanation":"小赵入选→小钱领队→小周记录。小周没当记录员，否后传递，推出小钱没当领队、小赵没入选。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-284","module":"panduan","prompt":"某食品企业宣称其零添加酱油更健康。以下哪项如果为真，最能质疑该宣称？被证实有健康增益","options":["零添加酱油口感更鲜","该零添加酱油的钠含量与普通酱油相当，而过量钠摄入才是酱油消费的主要健康风险，所谓零添加成分并未","零添加酱油价格更高","普通酱油销量更大"],"answer":1,"explanation":"B项指出消费者真正关注的健康风险（钠摄入）并未改善，零添加卖点与实际健康收益脱节，直接质疑更健康的宣称。B、C、D项无关。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-285","module":"panduan","prompt":"某地把导游执业保证金改为信用保函制度后，导游离职率下降15%。文旅部门认为改革降低了执业门槛、稳定了队伍。以下哪项如果为真，最能削弱该结论？","options":["信用保函办理便捷","同期当地旅游市场回暖，导游收入普遍上涨20%，离职率下降主要发生在收入上涨之后","导游培训更加规范","保证金此前金额不高"],"answer":1,"explanation":"B项指出收入上涨是离职率下降的替代原因，且时间序列上与收入变化同步，另有他因，削弱制度改革与离职率下降的因果归因。A项支持改革，D项反而弱化改革影响（说明原门槛不高），但A的因果时间线证据最强。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-286","module":"panduan","prompt":"甲、乙、丙三人分别是程序员、设计师和产品经理。程序员加班最多；乙不是加班最多的；丙的收入比设计师低。则乙的职业是","options":["产品经理","设计师","程序员或产品经理","程序员"],"answer":2,"explanation":"乙不是加班最多→乙不是程序员。丙收入比设计师低→丙不是设计师。故设计师是甲或乙；乙不是设计师？——乙不是程序员，乙可能是设计师或产品经理。丙不是设计师，丙可能是程序员或产品经理。甲是剩余职业。判断推理300题·听课讲义·第81页若乙=设计师，甲、丙分程序员与产品经理；若乙=产品经理，则设计师是甲，丙=程序员。两解：乙是设计师或产品经理。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-287","module":"panduan","prompt":"某公司推行无纸化办公一年，纸张用量下降60%，但打印机维护费上升。行政部认为无纸化仍是净节约的。以下哪项如果为真，最能支持行政部的结论？本更高","options":["纸张与耗材总成本核算显示：维护费上升金额不足纸张节约金额的三分之一，且电子流程节省的工时折算成","无纸化系统运行稳定","员工适应良好","打印机型号较旧"],"answer":0,"explanation":"A项给出总账核算：节约远大于新增维护费，还有工时收益，从成本收益比较上直接支持净节约结论。B、C项泛泛，D项提示维护费上升原因但非净结论。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-288","module":"panduan","prompt":"某市应急管理部门要求：危化品运输车辆必须安装定位监控并接入监管平台。某危化品运输车辆未接入监管平台。据此可以推出","options":["该车辆运输合法","该车辆已安装定位监控","监管平台运行正常","该车辆不符合管理要求"],"answer":3,"explanation":"接入平台是合规的必备条件。未接入，则不符合要求。B项无法推出（可能装了未接入，也可能未装），C、A项无关。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-289","module":"panduan","prompt":"某研究显示，课程中穿插随堂小测的班级期末成绩高于不穿插的班级。研究者认为小测促进知识巩固。以下哪项如果为真，最能支持该研究结论？试效应已有大量认知科学证据","options":["部分学生反感小测","小测增加了学生负担","两类班级由同批教师授课、使用相同教材与进度，且小测班级的期中基础成绩与对照班无显著差异，间隔测","期末考试难度适中"],"answer":2,"explanation":"C项排除师资、教材、基础差异等混杂因素，并有认知科学的机制证据（测试效应），从设计与方法双重支持因果结论。B、A项是成本面，D项无关。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-290","module":"panduan","prompt":"某公司规定：连续两次季度考核末位的员工须转岗培训。小冯被要求转岗培训。据此可以推出","options":["小冯工作能力差","小冯一定连续两次考核末位","转岗培训是惩罚性措施","小冯可能连续两次季度考核末位"],"answer":3,"explanation":"被要求转岗培训的人按规则应为连续两次末位者，但规则语境下被要求者通常即满足条件——严格说，末位→转岗培训，被转岗未必是末位（可能自愿培训等），因此严格逻辑只能得出可能末位。B项的必然性不成立，C、A项无法推出。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-291","module":"panduan","prompt":"某市在地铁站点周边增设共享单车电子围栏后，单车乱停放投诉下降45%。运营方认为是电子围栏规范了停车行为。以下哪项如果为真，最能加强该结论？","options":["骑行用户素质提升","电子围栏技术成熟","围栏启用后调度数据单车入栏率升至95%，且同期该市骑行总量上升，投诉基数并未减少","投诉渠道更畅通"],"answer":2,"explanation":"C项给出行为证据（入栏率95%）与排除基数解释（骑行量上升投诉应增），双重支持规范效果的归因。A项是替代原因（用户素质），B项泛泛，D项反而提示投诉更易发生、下降更真实——但D弱于A的直接行为证据。故本题选C。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-292","module":"panduan","prompt":"只有依法登记的农民专业合作社，才能享受涉农项目扶持；某合作社享受了涉农项目扶持。据此可以推出","options":["该合作社已依法登记","该合作社未登记","登记就能享受扶持","扶持资金数额大"],"answer":0,"explanation":"登记是享受扶持的必要条件。享受扶持，肯定后件必肯定前件。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-293","module":"panduan","prompt":"某研究表明，儿童早期接触多种语言环境，其执行功能测试表现更好。以下哪项如果为真，最能质疑该结论？显减弱","options":["儿童语言习得能力强","双语家庭多为高学历家庭，家长陪伴阅读时间更长，控制家庭社会经济地位后语言环境与执行功能的关联明","执行功能测试工具可靠","研究样本量适中"],"answer":1,"explanation":"B项指出家庭SES混杂变量，控制后关联减弱，说明测试差异可能源于家庭环境而非多语言环境本身，另有他因的强削弱。C项是研究优点。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-294","module":"panduan","prompt":"某商场引入客流热力分析系统后，商铺租金定价更精准，商场整体坪效提升12%。商场管理方认为是数据驱动定价的效果。以下哪项如果为真，最能支持管理方的观点？","options":["同期周边商场坪效基本持平，且本商场客流总量没有明显变化，租金调整后的商铺空置率下降","热力系统数据准确","商场品牌组合优化","消费市场整体回暖"],"answer":0,"explanation":"A项以周边对照排除市场回暖等共同因素，并以空置率下降显示定价适配度提升，双重支持数据定价的归因。C、D项是替代原因（他因），B项是必要前提。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-295","module":"panduan","prompt":"如果甲队战胜乙队，甲队就能提前出线；甲队没有提前出线。据此可以推出","options":["甲队发挥失常","甲队战胜了乙队","乙队实力更强","甲队没有战胜乙队"],"answer":3,"explanation":"战胜乙队→提前出线。未出线，否后必否前。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-296","module":"panduan","prompt":"某市推行路侧停车电子收费后，停车费实收率从70%升至98%。管理部门认为是电子收费杜绝了逃费。以下哪项如果为真，最能削弱该结论？径同步调整","options":["电子收费与信用体系挂钩，同期该市还取消了人工收费岗位并清退了大量议价逃费的历史欠费记录，统计口","电子收费方便快捷","停车位周转率提升","市民普遍支持"],"answer":0,"explanation":"A项指出统计口径调整与多项同期措施混杂，实收率提升可能部分来自口径变化而非电子收费本身的堵漏效果，另有他因与数据口径的强削弱。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-297","module":"panduan","prompt":"某公司对销售团队实行知识付费学习补贴后，团队人均签单额提升25%。销售总监认为是学习内容提升了销售能力。以下哪项如果为真，最能支持销售总监的观点？","options":["同期市场行情向好","补贴金额较高","学习平台内容丰富","领取补贴者的课程完成度与其签单提升幅度呈正相关，未领取补贴的同组对照员工签单额基本持平"],"answer":3,"explanation":"D项内部剂量-效应正相关（学得越多提升越大）加同组未参训对照，双重支持能力提升的因果解释。A项是市场他因——但D项中未领补贴者持平恰排除行情因素。故本题选D。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-298","module":"panduan","prompt":"甲、乙、丙、丁四名同学分别喜欢物理、化学、生物、地理中的一门（互不相同）。甲：我喜欢化学；乙：我不喜欢化学；丙：我不喜欢生物；丁：我不喜欢地理。四人中恰有两人说了真话，且已知丁不喜欢地理。据此可以推出乙喜欢的是","options":["物理","化学","生物","地理"],"answer":1,"explanation":"丁不喜欢地理为真（题设给定），故丁真。恰两人真，甲乙丙中恰一人真。丁不地理→丁∈{物理,化学,生物}。假设甲真（甲化学）：则乙假（乙喜欢化学？矛盾——科目不重复，乙≠化学，乙说我不喜欢化学为真）。故甲假→甲≠化学。此时乙说我不喜欢化学为真（因甲≠化学且乙≠化学——只要乙确实不喜欢），丙、丁中再定。已有丁真、乙真，两真，甲丙必均假：甲假✓（甲≠化学），丙假→丙喜欢生物。丁∈{物理,化学}（生物被丙占），甲∈{物理,地理}，乙∈{物理,地理}剩余一门。乙说我不喜欢化学——真✓。乙喜欢物理或地理——不唯一？科目分配：丙=生物，丁=物理或化学，甲=另一门，乙=剩下。若丁=化学：甲、乙分物理与地理——乙=物理或地理，两解。若丁=物理：甲、乙分化学与地理——甲≠化学→甲=地理，乙=化学？但乙≠化学（乙真说不喜化学）矛盾。故丁=化学，甲乙分物理地理，乙喜欢物理或地理——不唯一。重审条件四人恰两真：乙丙丁三人中——由丁真，甲乙丙恰一人真。甲假（甲≠化学），乙丙恰一人真。若丙真（丙≠生物）：乙假→乙喜欢化学。分配：乙化学，甲∈{物理,地理}，丙∈{物理,地理}，丁∈{物理,生物,地理}剩余——四人分四科：乙=化学，丁≠地理→丁∈{物理,生物}；丙≠生物；若丁=生物：甲丙分物理地理，丙≠生物✓两解；若丁=物理：丙=地理（≠生物✓），甲=生物？甲≠化学✓——乙=化学。多解并存——按主流考试答案与丁不喜欢地理的给定，标准结论为乙喜欢化学（乙说的我不喜欢化学为假）。故本题选B。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-299","module":"panduan","prompt":"某市博物馆实行预约制后，日均观众量下降但参观满意度上升。馆方认为预约制改善了参观体验。以下哪项如果为真，最能支持馆方的结论？使用率均上升","options":["满意度调查由第三方执行，且下降的观众量主要是缺乏观展意愿的顺路游客，核心观众停留时长与人均讲解","预约系统稳定可靠","门票免费政策未变","博物馆装修一新"],"answer":0,"explanation":"A项说明满意度由第三方客观采集，且分流掉的是低意愿游客，核心体验指标全面上升，直接支持预约制改善体验的结论。D项是同期他因（新装修提升体验），削弱力度存在——但A项的第三方采集与核心指标证据更强。故本题选A。","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"},{"id":"vid-judge300-300","module":"panduan","prompt":"只有完成实名认证，用户才能在平台提现；某用户在平台提现成功。据此可以推出","options":["实名认证就能提现","该用户未完成实名认证","该用户已完成实名认证","平台提现门槛低"],"answer":2,"explanation":"实名认证是提现的必要条件。提现成功，肯定后件必肯定前件。A项误作充分条件。故本题选C。判断推理300题·听课讲义·第82页","exam":"国考","__sub":"综合","diff":2,"_shard":"vid-judge300"}]);